// ── UZMED AI — xavfsiz proxy bo’lsa online, aks holda lokal fallback ──
const AI_SYSTEM = `Sen UZMED tibbiy yordamchisisan. O’zbekiston shifokorlari va tibbiyot mutaxassislari uchun ishlaydigan ixtisoslashgan AI.

Asosiy yo’nalishlar:
- Allergologiya (allergik rinitlar, bronxial astma, atopik dermatit, urtikaria, anafilaksiya)
- Dermatologiya (teri kasalliklari, autoimmun teri kasalliklari)
- MKB-10 kodlari va tasnifi
- Dori vositalari (INN nomlar, dozalash, o’zaro ta’sir)
- Klinik protokollar

Javob berish qoidalari:
1. O’zbek tilida, sodda va aniq javob ber
2. Tibbiy terminlarni tushuntir
3. MKB-10 kodlarini albatta keltir (agar mavjud bo’lsa)
4. Dori dozalarini yoshga qarab keltir (bolalar va kattalarda)
5. Muhim ogohlantirishlarni ** ** orasida yoz
6. Jiddiy holatlarda zudlik bilan shifokorga murojaat qilishni maslahat ber
7. Javoblarni qisqa va amaliy qil

Eslatma: Sen professional tibbiy maslahat bera olasan, lekin bemorni ko’rgan shifokor qarorini o’zgartira olmaysan.`;

let aiHistory = [];
// ── Suhbat xotirasini saqlash (sahifa yangilansa ham eslab qoladi) ──
(function () {
  try {
    var saved = localStorage.getItem('UZMED_AI_HISTORY');
    if (saved) { var arr = JSON.parse(saved); if (Array.isArray(arr)) aiHistory = arr; }
  } catch (e) {}
  try { window.aiHistory = aiHistory; } catch (e) {}
})();
window.uzmedSaveHistory = function () {
  try {
    var src = window.aiHistory || aiHistory || [];
    var slim = src.slice(-20).map(function (m) {
      return { role: m.role, parts: [{ text: (m.parts && m.parts[0] && m.parts[0].text) || '' }] };
    });
    localStorage.setItem('UZMED_AI_HISTORY', JSON.stringify(slim));
  } catch (e) {}
};
// aiHistory.push har chaqirilganda avtomatik saqlansin (window.aiHistory ustida)
window.uzmedHookHistory = function () {
  try {
    var a = window.aiHistory;
    if (a && !a.__hooked) {
      var orig = a.push;
      a.push = function () { var r = orig.apply(this, arguments); window.uzmedSaveHistory(); return r; };
      Object.defineProperty(a, '__hooked', { value: true, enumerable: false });
    }
  } catch (e) {}
};
window.uzmedHookHistory();
let aiTyping = false;
const UZMED_AI_PROXY_ENDPOINT = (function(){
  try {
    return localStorage.getItem('UZMED_AI_ENDPOINT') || window.UZMED_AI_ENDPOINT || '';
  } catch(e) {
    return window.UZMED_AI_ENDPOINT || '';
  }
})();

function getAiTime() {
  const now = new Date();
  return now.getHours().toString().padStart(2,'0') + ':' + now.getMinutes().toString().padStart(2,'0');
}

function formatAiText(text) {
  return String(text == null ? '' : text)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/`(.*?)`/g, '<code>$1</code>')
    .replace(/\n/g, '<br>');
}

function appendUserMsg(text) {
  const wrap = document.getElementById('aiMessages');
  const welcome = wrap.querySelector('.ai-welcome');
  if (welcome) welcome.style.display = 'none';

  wrap.innerHTML += `
    <div class="ai-msg-row user">
      <div class="ai-msg-avatar user"><i class=uzi101></i></div>
      <div class="ai-bubble user">${text.replace(/</g,'&lt;').replace(/>/g,'&gt;')}</div>
    </div>
    <div class="ai-time">${getAiTime()}</div>`;
  wrap.scrollTop = wrap.scrollHeight;
}

function appendBotMsg(text) {
  const wrap = document.getElementById('aiMessages');
  wrap.innerHTML += `
    <div class="ai-msg-row">
      <div class="ai-msg-avatar bot"><i class=uzi139></i></div>
      <div class="ai-bubble bot">${formatAiText(text)}</div>
    </div>
    <div class="ai-time bot">${getAiTime()}</div>`;
  wrap.scrollTop = wrap.scrollHeight;
}

// ── Saqlangan suhbatni ekranga qayta chizish (sahifa yangilangach) ──
let _uzmedHistoryRestored = false;
function uzmedRestoreChatUI() {
  try {
    if (_uzmedHistoryRestored) return;
    var src = (window.aiHistory || aiHistory || []);
    if (!src.length) return;
    var wrap = document.getElementById('aiMessages');
    if (!wrap) return;
    var welcome = wrap.querySelector('.ai-welcome');
    if (welcome) welcome.style.display = 'none';
    src.forEach(function (m) {
      var t = (m.parts && m.parts[0] && m.parts[0].text) || '';
      if (!t) return;
      if (m.role === 'model') appendBotMsg(t); else appendUserMsg(t);
    });
    _uzmedHistoryRestored = true;
  } catch (e) {}
}
window.uzmedRestoreChatUI = uzmedRestoreChatUI;

function showTyping() {
  const wrap = document.getElementById('aiMessages');
  wrap.innerHTML += `
    <div class="ai-msg-row" id="aiTypingRow">
      <div class="ai-msg-avatar bot"><i class=uzi139></i></div>
      <div class="ai-bubble bot"><div class="ai-typing"><span></span><span></span><span></span></div></div>
    </div>`;
  wrap.scrollTop = wrap.scrollHeight;
}

function hideTyping() {
  const row = document.getElementById('aiTypingRow');
  if (row) row.remove();
}

function getUzmedAiEndpoint() {
  try {
    return localStorage.getItem('UZMED_AI_ENDPOINT') || window.UZMED_AI_ENDPOINT || UZMED_AI_PROXY_ENDPOINT || '';
  } catch(e) {
    return window.UZMED_AI_ENDPOINT || UZMED_AI_PROXY_ENDPOINT || '';
  }
}

window.setUzmedAiEndpoint = function(url) {
  try {
    localStorage.setItem('UZMED_AI_ENDPOINT', String(url || '').trim());
  } catch(e) {}
  window.UZMED_AI_ENDPOINT = String(url || '').trim();
  toast(url ? 'UZMED AI endpoint saqlandi' : 'UZMED AI endpoint o‘chirildi');
};



