function uzmedNorm(x){ return String(x||'').toLowerCase().replace(/ё/g,'е').trim(); }
/* lotin/cyrillic kiritmani cyrillic INN ga aylantiradi (KB ichidan) */
function uzmedResolveInnKB(ql){
  ql=uzmedNorm(ql);
  if(!ql || ql.length<3) return null;
  var keys=Object.keys(UZMED_DRUG_KB);
  for(var i=0;i<keys.length;i++){
    var k=keys[i], e=UZMED_DRUG_KB[k];
    if(uzmedNorm(k)===ql) return k;
    var lats=(e.lat||[]);
    for(var j=0;j<lats.length;j++){ var L=uzmedNorm(lats[j]); if(L && (L===ql || ql.indexOf(L)>=0 || L.indexOf(ql)>=0)) return k; }
  }
  // qisman (substring) cyrillic
  for(var a=0;a<keys.length;a++){ if(uzmedNorm(keys[a]).indexOf(ql)>=0 || ql.indexOf(uzmedNorm(keys[a]))>=0) return keys[a]; }
  return null;
}

/* ════════════════════════════════════════════════════════════
   UZMED OFFLINE KB — MKB-10 (15588) + DRUG_DATA (12630) + protokollar
   Tashxis/kod yozilsa: nomi + O'zbek standart davolash + dorilar + ADTI narx
   ════════════════════════════════════════════════════════════ */
function uzmedKB(){
  return {
    MKB:  (typeof MKB_DATA!=='undefined')?MKB_DATA:(window.MKB_DATA||[]),
    PROTO:(typeof DISEASE_PROTOCOLS!=='undefined')?DISEASE_PROTOCOLS:(window.DISEASE_PROTOCOLS||{}),
    DD:   (typeof DRUG_DATA!=='undefined')?DRUG_DATA:(window.DRUG_DATA||[]),
    SECT: (typeof MKB_SECTIONS!=='undefined')?MKB_SECTIONS:(window.MKB_SECTIONS||{}),
    ADET: (typeof ALLERGY_DRUG_DETAILS!=='undefined')?ALLERGY_DRUG_DETAILS:(window.ALLERGY_DRUG_DETAILS||{})
  };
}
function uzmedSectMap(){
  if(window.__uzmedSectMap) return window.__uzmedSectMap;
  var m={}; var SECT=uzmedKB().SECT;
  try{
    Object.keys(SECT).forEach(function(k){
      var sec=SECT[k]; if(!sec||!sec.codes) return;
      sec.codes.forEach(function(c){ if(c&&c.code) m[c.code]=(c.inns||[]); });
    });
  }catch(e){}
  window.__uzmedSectMap=m; return m;
}
function uzmedPrice(r){ try{ return parseFloat(String(r[5]||'').replace(/\s/g,''))||1e15; }catch(e){ return 1e15; } }
function uzmedDrugsForInn(inn){
  var DD=uzmedKB().DD, innl=String(inn||'').toLowerCase().trim();
  if(!innl) return [];
  var rows=DD.filter(function(r){ return r&&r[1]&&String(r[1]).toLowerCase()===innl; });
  rows.sort(function(a,b){ return uzmedPrice(a)-uzmedPrice(b); });
  return rows;
}
function uzmedInnsForCode(code){
  var map=uzmedSectMap();
  var base=String(code).split('.')[0];
  var inns=(map[code]||map[base]||[]).slice();
  return inns.filter(function(v,i,a){return v&&a.indexOf(v)===i;});
}

/* Cyrillic → lotin transliteratsiya (qidiruv uchun) */
function uzmedTranslit(x){
  var map={'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'yo','ж':'zh','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'x','ц':'ts','ч':'ch','ш':'sh','щ':'sch','ъ':'','ы':'i','ь':'','э':'e','ю':'yu','я':'ya'};
  return String(x||'').toLowerCase().split('').map(function(c){ return (c in map)?map[c]:c; }).join('');
}
/* DRUG_DATA dagi barcha noyob INN (1655) — lotin variantlari bilan indeks (1 marta quriladi) */
function uzmedInnIndex(){
  if(window.__uzmedInnIndex) return window.__uzmedInnIndex;
  var DD=uzmedKB().DD, seen={}, list=[];
  try{
    DD.forEach(function(r){ if(r&&r[1]){ var k=String(r[1]).toLowerCase().trim(); if(k && !seen[k]){ seen[k]=1; list.push({inn:k, lat:uzmedTranslit(k)}); } } });
  }catch(e){}
  window.__uzmedInnIndex=list; return list;
}
/* kiritmani (lotin yoki cyrillic) DRUG_DATA dagi haqiqiy INN ga moslaydi */
function uzmedResolveAnyInn(ql){
  var nq=String(ql||'').toLowerCase().replace(/[^a-zа-яё0-9]/gi,'');
  if(nq.length<3) return null;
  var idx=uzmedInnIndex();
  // 1) to'liq mos
  for(var i=0;i<idx.length;i++){
    var ci=idx[i].inn.replace(/[^a-zа-яё0-9]/gi,'');
    var li=idx[i].lat.replace(/[^a-z0-9]/gi,'');
    if(ci===nq || li===nq) return idx[i].inn;
  }
  // 2) qisman mos (eng uzun moslik)
  var best=null,bl=0;
  for(var j=0;j<idx.length;j++){
    var ci2=idx[j].inn.replace(/[^a-zа-яё0-9]/gi,'');
    var li2=idx[j].lat.replace(/[^a-z0-9]/gi,'');
    if(li2.length>3 && (li2.indexOf(nq)>=0 || nq.indexOf(li2)>=0)){ if(li2.length>bl){bl=li2.length;best=idx[j].inn;} }
    else if(ci2.length>3 && ci2.indexOf(nq)>=0){ if(ci2.length>bl){bl=ci2.length;best=idx[j].inn;} }
  }
  return best;
}


/* Barcha 12630 preparat brend indeksi (lotin/cyrillic qidiruv) */
function uzmedBrandIndex(){
  if(window.__uzmedBrandIndex) return window.__uzmedBrandIndex;
  var DD=uzmedKB().DD, list=[];
  try{ DD.forEach(function(r,ix){ if(r&&r[0]) list.push({row:r, brand:String(r[0]).toLowerCase().trim(), inn:String(r[1]||'').toLowerCase().trim(), lat:uzmedTranslit(String(r[0]).toLowerCase())}); }); }catch(e){}
  window.__uzmedBrandIndex=list; return list;
}
function uzmedResolveBrand(ql){
  var nq=String(ql||'').toLowerCase().replace(/[^a-zа-яё0-9]/gi,'');
  if(nq.length<3) return null;
  var idx=uzmedBrandIndex();
  for(var i=0;i<idx.length;i++){ var b=idx[i].brand.replace(/[^a-zа-яё0-9]/gi,''); var l=idx[i].lat.replace(/[^a-z0-9]/gi,''); if(b===nq||l===nq) return idx[i]; }
  var best=null,bl=0;
  for(var j=0;j<idx.length;j++){ var b2=idx[j].brand.replace(/[^a-zа-яё0-9]/gi,''); var l2=idx[j].lat.replace(/[^a-z0-9]/gi,''); if(b2.length>3&&b2.indexOf(nq)>=0){ if(b2.length>bl){bl=b2.length;best=idx[j];} } else if(l2.length>3&&l2.indexOf(nq)>=0){ if(l2.length>bl){bl=l2.length;best=idx[j];} } }
  return best;
}


/* MKB kod kaliti (tartiblash/diapazon uchun): harf+2 raqam */
function uzmedCodeKey(c){ var m=String(c||'').toUpperCase().match(/^([A-Z])(\d{2})/); if(!m) return -1; return m[1].charCodeAt(0)*100 + parseInt(m[2],10); }
/* Kodning sinfi (bob), bloki va ichki kodlari — faqat MKB_DATA dan */
function uzmedMkbContext(code){
  var MKB=uzmedKB().MKB;
  var pm=String(code||'').toUpperCase().match(/^[A-Z]\d{2}/); var pref=pm?pm[0]:String(code).toUpperCase();
  var key=uzmedCodeKey(pref), blocks=[], subs=[];
  for(var i=0;i<MKB.length;i++){ var r=MKB[i]; if(!r||!r[0]) continue; var cc=String(r[0]);
    if(/^[A-Z]\d{2}-[A-Z]\d{2}$/.test(cc)){ var a=uzmedCodeKey(cc.slice(0,3)), b=uzmedCodeKey(cc.slice(4,7)); if(key>=a && key<=b){ blocks.push({code:cc,name:r[1],span:(b-a)}); } }
    else if(cc.indexOf(pref+'.')===0){ subs.push(r); }
  }
  blocks.sort(function(a,b){return a.span-b.span;});
  return { block: blocks.length?blocks[0]:null, chapter: blocks.length?blocks[blocks.length-1]:null, subs:subs };
}

/* asosiy javob — string yoki null */
/* ── UZMED: umumiy/filler so'zlar — noto'g'ri MKB/protokol mosligini bartaraf etadi ── */
var UZMED_QSTOP={dori:1,dorilar:1,dorisi:1,dorini:1,doriga:1,doridan:1,preparat:1,preparati:1,preparatni:1,preparatlar:1,vosita:1,vositalar:1,vositasi:1,kasallik:1,kasalligi:1,kasal:1,kasallikni:1,haqida:1,haqda:1,haqidagi:1,nima:1,nimadan:1,qanday:1,qaysi:1,menga:1,kerak:1,uchun:1,bilan:1,yoki:1,boyicha:1,davo:1,davosi:1,davolash:1,davolashda:1,belgilari:1,belgisi:1,belgilar:1,sabab:1,sabablari:1,tavsif:1,malumot:1,ichki:1,bormi:1,nimaga:1,'лекарство':1,'препарат':1,'препараты':1,'средство':1,'болезнь':1,'что':1,'как':1,'какой':1,'при':1,'для':1,'это':1,'лечение':1};
function uzmedTok(s,minLen){ return String(s||'').toLowerCase().split(/[^a-zа-яё0-9’']+/i).filter(function(w){ return w.length>(minLen||3) && !UZMED_QSTOP[w]; }); }
function uzmedFullKbAnswer(rawq){
  try{
    var KB=uzmedKB(), MKB=KB.MKB, PROTO=KB.PROTO, ADET=KB.ADET;
    if(!MKB.length) return null;
    var q=String(rawq||'').trim(); if(q.length<2) return null;
    var ql=q.toLowerCase();
    var isCode=/^[a-z]\d{2}(\.\d+)?$/i.test(q.replace(/\s/g,''));

    /* ── 1) DORI / PREPARAT nomi bo'yicha — 1655 INN + 12630 preparat (offline) ── */
    if(!isCode){
      var DD=KB.DD;
      var kbInn = (typeof uzmedResolveInnKB==='function') ? uzmedResolveInnKB(ql) : null;
      var adKeys=Object.keys(ADET);
      var adHit=adKeys.filter(function(k){ return ql.length>3 && (k.indexOf(ql)>=0 || ql.indexOf(k)>=0 || (ADET[k].brands||'').toLowerCase().indexOf(ql)>=0); })[0];
      var anyInn = (typeof uzmedResolveAnyInn==='function') ? uzmedResolveAnyInn(ql) : null;
      var brandHit = (typeof uzmedResolveBrand==='function') ? uzmedResolveBrand(ql) : null;
      var innForPrice = anyInn || (brandHit?brandHit.inn:null) || kbInn;

      if(kbInn || adHit || innForPrice){
        var out='';
        // Aniq preparat (brend) topilsa — to'liq ma'lumoti
        if(brandHit && brandHit.row){
          var br=brandHit.row;
          out += '**<i class=uzi44></i> Topilgan preparat: '+br[0]+'**\n';
          out += '- INN (xalqaro nomi): '+(br[1]||'—')+'\n';
          out += '- Ishlab chiqaruvchi: '+(br[2]||'—')+'\n';
          out += '- Shakli/dozasi: '+(br[3]||'—')+'\n';
          out += '- ADTI narxi: '+(br[5]||'—')+' '+(br[4]||'')+'\n\n';
        }
        // Farmakologik tavsif (ichki KB yoki allergiya bazasi)
        if(kbInn){
          var e=UZMED_DRUG_KB[kbInn];
          out += '**'+kbInn.charAt(0).toUpperCase()+kbInn.slice(1)+' — farmakologik ma’lumot:**\n\n';
          if(e.g) out+='**Guruh:** '+e.g+'\n\n';
          if(e.i) out+='**Ko‘rsatmalar:** '+e.i+'\n\n';
          if(e.d) out+='**Dozalash (kattalar):** '+e.d+'\n\n';
          if(e.c) out+='**Qarshi ko‘rsatmalar:** '+e.c+'\n\n';
          if(e.s) out+='**Nojo‘ya ta’sirlar:** '+e.s+'\n\n';
        } else if(adHit){
          var d=ADET[adHit];
          out += '**'+(d.brands||adHit)+' ('+adHit+') — farmakologik ma’lumot:**\n\n';
          if(d.cat)  out+='**Guruh:** '+d.cat+'\n\n';
          if(d.form) out+='**Shakllari:** '+d.form+'\n\n';
          if(d.dose) out+='**Dozalash:** '+d.dose+'\n\n';
          if(d.max)  out+='**Maksimal doza:** '+d.max+'\n\n';
          if(d.contra)out+='**Qarshi ko‘rsatmalar:** '+d.contra+'\n\n';
          if(d.side) out+='**Nojo‘ya ta’sirlar:** '+d.side+'\n\n';
          if(d.note) out+='**Izoh:** '+d.note+'\n\n';
        }
        // Shu INN bo'yicha BARCHA preparatlar (to'liq ma'lumot bilan)
        if(innForPrice){
          var rows=uzmedDrugsForInn(innForPrice);
          if(rows.length){
            out += '**<i class=uzi10></i> «'+innForPrice+'» bo‘yicha bazada '+rows.length+' ta preparat (ADTI narxi bo‘yicha arzondan):**\n';
            var lim=Math.min(rows.length,40);
            for(var ri=0; ri<lim; ri++){ var r=rows[ri];
              out += (ri+1)+'. '+r[0]+' — '+(r[3]||'')+' — '+(r[2]||'')+' — '+(r[5]||'?')+' '+(r[4]||'')+'\n';
            }
            if(rows.length>lim){ out += '… va yana '+(rows.length-lim)+' ta preparat (bazada mavjud).\n'; }
            out += '\n';
          }
        }
        if(!kbInn && !adHit){
          out += '_Eslatma: preparatlar va narxlar ilova bazasidan. Batafsil farmakologik tavsif (doza/qarshi ko‘rsatma) bu INN uchun hozircha kiritilmagan — preparat annotatsiyasiga qarang._\n\n';
        }
        out += '<i class=uzi23></i> Ma’lumot UZMED ichki bazasidan (12 630 preparat / 1 655 INN). Dozani shifokor tasdiqlaydi.';
        return out;
      }
    }

    /* ── 1.5) DERMATOLOGIYA (DERMA_DATA) — nom yoki MKB kod bo'yicha ── */
    try{
      var DM=(typeof DERMA_DATA!=='undefined')?DERMA_DATA:(window.DERMA_DATA||{});
      var DIMG=(typeof DISEASE_IMGS!=='undefined')?DISEASE_IMGS:(window.DISEASE_IMGS||{});
      var dkeys=Object.keys(DM), dHit=null, dKey=null;
      var qcode=q.replace(/\s/g,'').toLowerCase();
      var dtoks=ql.split(/[^a-z\u0400-\u04FF0-9\u2019']+/i).filter(function(w){return w.length>3 && !UZMED_QSTOP[w];});
      for(var di=0; di<dkeys.length; di++){
        var dd=DM[dkeys[di]]; if(!dd) continue;
        if(isCode){ if(dd.mkb && String(dd.mkb).toLowerCase()===qcode){ dHit=dd; dKey=dkeys[di]; break; } continue; }
        var hay=((dd.uz||'')+' '+(dd.ru||'')+' '+dkeys[di]).toLowerCase();
        if(dtoks.length && dtoks.every(function(w){return hay.indexOf(w)>=0;})){ dHit=dd; dKey=dkeys[di]; break; }
      }
      if(dHit){
        var o='';
        var dimg = dKey ? DIMG[dKey] : null;
        if(dimg){ o += '<img src="'+dimg+'" alt="'+(dHit.uz||'')+'" style="max-width:100%;border-radius:12px;margin:2px 0 10px;display:block">'; }
        o+='**'+(dHit.uz||'')+'**'+(dHit.mkb?' (MKB-10: '+dHit.mkb+')':'')+'\n'+(dHit.ru?'_'+dHit.ru+'_\n':'')+'\n';
        if(dHit.sev) o+='**Og‘irlik darajasi:** '+dHit.sev+'\n\n';
        if(dHit.tarif) o+='**Ta’rif:** '+dHit.tarif+'\n\n';
        if(dHit.belgilar) o+='**Belgilari:**\n'+dHit.belgilar+'\n\n';
        if(dHit.davolash) o+='**Davolash:**\n'+dHit.davolash+'\n\n';
        if(dHit.chegara) o+='**Chegara / mezon:** '+dHit.chegara+'\n\n';
        if(dHit.farq) o+='**Farqlash (differensial):** '+dHit.farq+'\n\n';
        o+='<i class=uzi23></i> Ma’lumot UZMED dermatologiya bazasidan. Yakuniy tashxisni shifokor tasdiqlaydi.';
        return o;
      }
    }catch(e){}

    /* ── 2) TASHXIS / MKB kod bo'yicha ── */
    var found=null;
    if(isCode){
      var c=q.replace(/\s/g,'').toUpperCase();
      found=MKB.find(function(r){return r[0]===c;}) || MKB.find(function(r){return /^[A-Z]\d{2}(\.\d+)?$/.test(r[0]) && r[0].indexOf(c)===0;});
    }
    if(!found){
      var toks=uzmedTok(ql,3);
      if(toks.length){
        var best=null,bs=0;
        for(var i=0;i<MKB.length;i++){
          var r=MKB[i]; if(!r||!r[0]||!/^[A-Z]\d{2}(\.\d+)?$/.test(r[0])) continue;
          var hay=((r[1]||'')+' '+(r[2]||'')).toLowerCase();
          var sc=0; toks.forEach(function(w){ if(hay.indexOf(w)>=0) sc++; });
          if(sc>bs){bs=sc;best=r;}
        }
        if(bs>0) found=best;
      }
    }
    if(!found) return null;

    var code=found[0], name=found[1], ru=found[2];
    var p=PROTO[code]||PROTO[String(code).split('.')[0]];
    var out='**'+name+'**  (MKB-10: '+code+')\n'+(ru?'_'+ru+'_\n':'')+'\n';

    try{
      var ctx=uzmedMkbContext(code);
      if(ctx.chapter && ctx.chapter.code!==code){ out+='**Sinf:** '+ctx.chapter.code+' — '+ctx.chapter.name+'\n'; }
      if(ctx.block && ctx.block.code!==code && (!ctx.chapter || ctx.block.code!==ctx.chapter.code)){ out+='**Blok:** '+ctx.block.code+' — '+ctx.block.name+'\n'; }
      if(ctx.subs && ctx.subs.length){
        out+='\n**Ichki kodlar ('+ctx.subs.length+' ta):**\n';
        ctx.subs.slice(0,20).forEach(function(r){ out+='• '+r[0]+' — '+(r[1]||'')+'\n'; });
        if(ctx.subs.length>20) out+='… va yana '+(ctx.subs.length-20)+' ta ichki kod.\n';
      }
      out+='\n';
    }catch(e){}

    if(p){
      out+='**<i class=uzi49></i> Standart davolash (O‘zbekiston sog‘liqni saqlash protokoli asosida):**\n\n';
      if(p.diag)  out+='**Tashxis va belgilar:** '+p.diag+'\n\n';
      if(p.first) out+='**Birinchi qator terapiya:** '+p.first+'\n\n';
      if(p.alt)   out+='**Muqobil / qo‘shimcha:** '+p.alt+'\n\n';
      if(p.dose)  out+='**Dozalash:** '+p.dose+'\n\n';
      if(p.emerg) out+='**<i class=uzi46></i> Shoshilinch holat:** '+p.emerg+'\n\n';
    } else {
      out+='_Bu kod uchun ilova bazasida batafsil davolash protokoli kiritilmagan. Quyida MKB nomi va (mavjud bo‘lsa) tegishli preparatlar keltirildi._\n\n';
    }

    var inns=uzmedInnsForCode(code);
    if(inns.length){
      out+='**<i class=uzi10></i> Tavsiya etiladigan preparatlar va ADTI narxlari:**\n';
      inns.slice(0,6).forEach(function(inn){
        var ds=uzmedDrugsForInn(inn);
        if(ds.length){
          out+='\n• **'+inn+'** ('+ds.length+' ta preparat mavjud) — arzonlari:\n';
          ds.slice(0,3).forEach(function(r){ out+='   - '+r[0]+' — '+(r[3]||'')+' — '+(r[5]||'?')+' '+(r[4]||'')+'\n'; });
        } else {
          out+='\n• **'+inn+'** — narx bazada topilmadi.\n';
        }
      });
      out+='\n';
    }
    out+='<i class=uzi23></i> Ma’lumot UZMED ichki bazasidan (MKB-10 + dorilar bazasi). Yakuniy tashxis va retseptni shifokor tasdiqlaydi.';
    return out;
  }catch(e){ return null; }
}

function localUzmedAiAnswer(text) {
  // ── Avval to'liq KB rezolveri (MKB-10 + dorilar + protokollar) ──
  try { var __kb = uzmedFullKbAnswer(text); if (__kb) return __kb; } catch(e){}
  const q = String(text || '').toLowerCase();
  function cleanList(items, max) {
    return (Array.isArray(items) ? items : (items ? [items] : []))
      .filter(Boolean).slice(0, max || 4).map((x, i) => (i + 1) + '. ' + String(x)).join('\n');
  }
  function drugLine(x) {
    if (!x) return '';
    return '- ' + (x.drug || x.name || 'Dori') + ': ' + (x.dose || '') +
      (x.route ? '; yo‘li: ' + x.route : '') +
      (x.frequency ? '; ' + x.frequency : '') +
      (x.duration ? '; davomiyligi: ' + x.duration : '');
  }
  function findProtocol() {
    const db = window.PROTOCOL_DB || {};
    const words = q.split(/[\s,.;:!?()]+/).filter(w => w.length > 2 && !UZMED_QSTOP[w]);
    let best = null, score = 0;
    Object.keys(db).forEach(id => {
      const d = db[id];
      const hay = JSON.stringify({
        id: d.id, name: d.name, icd: d.icd, description: d.description,
        symptoms: d.symptoms, criteria: d.criteria, treatment: d.treatment,
        first_line: d.first_line, alternative: d.alternative
      }).toLowerCase();
      let s = 0;
      words.forEach(w => { if (hay.includes(w)) s++; });
      if (s > score) { score = s; best = d; }
    });
    return score ? best : null;
  }
  function findDrugInfo() {
    const db = window.FULL_DRUG_DB || {};
    const details = window.ALLERGY_DRUG_DETAILS || {};
    const words = q.split(/[\s,.;:!?()]+/).filter(w => w.length > 3 && !UZMED_QSTOP[w]);
    const keys = Object.keys(db).concat(Object.keys(details));
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i].toLowerCase();
      if (words.some(w => k.includes(w) || w.includes(k))) {
        return db[keys[i]] || details[keys[i]];
      }
    }
    return null;
  }
  const proto = findProtocol();
  if (proto) {
    const first = (proto.first_line || []).slice(0, 6).map(drugLine).join('\n');
    const alt = (proto.alternative || []).slice(0, 4).map(drugLine).join('\n');
    const defTxt = Array.isArray(proto.definition) ? proto.definition.join(' ') : (proto.definition || proto.description || 'Bu holat uchun UZMED ichki bazasida klinik protokol mavjud.');
    return `**${proto.name}**${proto.icd ? ' (MKB/ICD: ' + proto.icd + ')' : ''}\n\n` +
      `**Bu nima?** ${defTxt}\n\n` +
      `**Asosiy belgilari:**\n${cleanList(proto.symptoms, 8) || '1. Klinik ko‘rinish va anamnez bo‘yicha baholanadi.'}\n\n` +
      `**Qanday aniqlanadi (diagnostika):**\n${cleanList(proto.criteria || proto.diagnostics, 8) || '1. Shifokor ko‘rigi, anamnez va kerakli tahlillar asosida.'}\n\n` +
      `**Birinchi qator davolash:**\n${first || cleanList(proto.treatment, 8) || 'Tashxis tasdiqlangach mutaxassis tomonidan belgilanadi.'}\n\n` +
      (alt ? `**Muqobil (qo‘shimcha) davolash:**\n${alt}\n\n` : '') +
      `**Shoshilinch belgilar:** nafas qisilishi, hushdan ketish, gipotenziya, tez rivojlanayotgan shish, qonli najas yoki og‘ir suvsizlanishda zudlik bilan shifokorga murojaat qiling.`;
  }
  const drug = findDrugInfo();
  if (drug) {
    return `**${drug.name || drug.brands || 'Dori ma’lumoti'}**\n\n` +
      `**Farmakologik guruhi:** ${drug.guruh || drug.cat || 'Ma’lumot bazasida mavjud'}\n\n` +
      `**Ko‘rsatmalar:** ${drug.korsatmalar || drug.ind || drug.note || 'Klinik holatga qarab qo‘llanadi.'}\n\n` +
      `**Dozalash:** ${drug.dozalash || drug.dose || 'Yosh, vazn va tashxisga qarab belgilanadi.'}\n\n` +
      `**Qarshi ko‘rsatmalar:** ${drug.qarshi || drug.contra || 'Preparatga yuqori sezgirlik va sinfga xos cheklovlar.'}\n\n` +
      `**Nojo‘ya ta’sirlar:** ${drug.yon || drug.side || 'Sinfga xos nojo‘ya ta’sirlar bo‘lishi mumkin.'}`;
  }
  if (q.includes('anafil') || q.includes('shok')) {
    return `**Anafilaksiyada birinchi qadam — adrenalin.**\n\n1. Allergen/dorini to‘xtating, yordam chaqiring.\n2. Adrenalin 1 mg/ml (1:1000) IM son mushagiga: kattalar 0.3–0.5 mg; bolalar 0.01 mg/kg.\n3. 5–15 daqiqada takrorlash mumkin.\n4. Kislorod, IV suyuqlik, salbutamol bronxospazmda.\n5. Antigistamin va steroid yordamchi, adrenalinni almashtirmaydi.`;
  }
  if (q.includes('astma')) {
    return `**Bronxial astma (MKB J45)**\n\nAsosiy belgilar: xirillash, nafas qisishi, yo‘tal, ko‘krak siqilishi. Tashxis spirometriya va bronxodilatator reversibiligi bilan tasdiqlanadi.\n\nDavolash: ICS asosidagi nazorat terapiyasi, xurujda salbutamol; og‘ir xurujda O2, salbutamol nebulayzer, prednizolon 1–2 mg/kg yoki kattalarda 40–50 mg/kun.`;
  }
  if (q.includes('urtik') || q.includes('eshak')) {
    return `**Urtikaria (MKB L50)**\n\nBirinchi qator: 2-avlod antigistaminlar — setirizin 10 mg/kun, loratadin 10 mg/kun yoki bilastin 20 mg/kun. Surunkali urtikariada doza shifokor nazoratida 4 baravargacha oshirilishi mumkin. Refrakter holatda omalizumab 300 mg SC har 4 haftada.`;
  }
  if (q.includes('rinit')) {
    return `**Allergik rinit (MKB J30)**\n\nBirinchi qator: intranazal kortikosteroid (flutikazon yoki mometazon) + 2-avlod antigistamin. Burun yuvish, allergen nazorati va tasdiqlangan IgE allergiyada 3–5 yil immunoterapiya ko‘rib chiqiladi.`;
  }
  return `Savolingiz bo‘yicha aniq tashxis yoki dori nomini yozing, men UZMED ichki bazasidan klinik protokolni chiqaraman.\n\nMasalan: **bronxial astma**, **anafilaksiya**, **allergik rinit**, **urtikaria**, **setirizin**, **prednizolon**, **adrenalin**.\n\nQisqa eslatma: tashxisda MKB kodi, og‘irlik darajasi, xavf belgilarini, kattalar/bolalar dozasini va shoshilinch holat mezonlarini alohida tekshirish kerak.`;
}

async function callUzmedAiProxy(text) {
  const endpoint = getUzmedAiEndpoint();
  if (!endpoint) return null;
  const messages = [
    { role: 'system', content: AI_SYSTEM },
    ...aiHistory.slice(-10).map(m => ({
      role: m.role === 'model' ? 'assistant' : 'user',
      content: (m.parts && m.parts[0] && m.parts[0].text) ? m.parts[0].text : ''
    })),
    { role: 'user', content: text }
  ];
  const res = await fetch(endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ messages, source: 'uzmed-html-ai' })
  });
  if (!res.ok) throw new Error('AI endpoint javob bermadi: ' + res.status);
  const data = await res.json();
  return data.answer || data.text || data.message || (data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || null;
}

/* ════════════════════════════════════════════════════════════════════
   UZMED OFLAYN AI — Qwen + Gemma qurilma ichida (WebLLM / WebGPU)
   Edge Gallery uslubida: model bir marta yuklab olinadi, soʼng internetsiz
   ishlaydi. Pulli yoki bulutli API umuman ishlatilmaydi.
   ════════════════════════════════════════════════════════════════════ */
const UZMED_WEBLLM_CDN = 'https://esm.run/@mlc-ai/web-llm';

const UZMED_LLM_DEFAULTS = { qwen: 'Qwen2.5-0.5B-Instruct-q4f32_1-MLC', gemma: 'gemma-2-2b-it-q4f32_1-MLC-1k' };

// Xotirani tejash uchun kontekst oynasi cheklangan (standart 32k KV-kesh juda katta
// ArrayBuffer talab qiladi va "allocation failed" xatosini keltirib chiqaradi).
const UZMED_CHAT_OPTS = { context_window_size: 1024 };

// f16 — kam xotira, lekin shader-f16 qoʼllab-quvvatlovchi qurilma kerak.
// f32 — koʼproq xotira, ammo deyarli barcha qurilmalarda ishlaydi.
const UZMED_LLM_CATALOG = {
  // ── Qwen ──
  'Qwen2.5-0.5B-Instruct-q4f32_1-MLC': { label: 'Qwen 2.5 — 0.5B (eng yengil · tavsiya)', fam: 'qwen', size: '~0.6 GB', f16: false },
  'Qwen2.5-0.5B-Instruct-q4f16_1-MLC': { label: 'Qwen 2.5 — 0.5B (f16 · eng kam xotira)', fam: 'qwen', size: '~0.4 GB', f16: true },
  'Qwen2.5-1.5B-Instruct-q4f16_1-MLC': { label: 'Qwen 2.5 — 1.5B (f16 · tejamkor)', fam: 'qwen', size: '~0.9 GB', f16: true },
  'Qwen2.5-1.5B-Instruct-q4f32_1-MLC': { label: 'Qwen 2.5 — 1.5B (kuchli)', fam: 'qwen', size: '~1.1 GB', f16: false },
  'Qwen2.5-3B-Instruct-q4f16_1-MLC':   { label: 'Qwen 2.5 — 3B (f16 · eng kuchli)', fam: 'qwen', size: '~1.7 GB', f16: true },
  // ── Gemma ──
  'gemma-2-2b-it-q4f16_1-MLC-1k':      { label: 'Gemma 2 — 2B (f16 · 1k · eng kam)', fam: 'gemma', size: '~1.0 GB', f16: true },
  'gemma-2-2b-it-q4f32_1-MLC-1k':      { label: 'Gemma 2 — 2B (1k · kam xotira · tavsiya)', fam: 'gemma', size: '~1.5 GB', f16: false },
  'gemma-2-2b-it-q4f16_1-MLC':         { label: 'Gemma 2 — 2B (f16 · toʼliq)', fam: 'gemma', size: '~1.3 GB', f16: true },
  'gemma-2-2b-it-q4f32_1-MLC':         { label: 'Gemma 2 — 2B (toʼliq kontekst)', fam: 'gemma', size: '~1.5 GB', f16: false }
};

let _uzmedLLM = { engine: null, current: null, mlc: null };
let _uzmedGpu = null;

// Qurilma imkoniyatlarini tekshirish (WebGPU, shader-f16, xotira chegarasi)
async function uzmedGpuProbe(){
  if (_uzmedGpu) return _uzmedGpu;
  var info = { webgpu: false, f16: false, maxBuffer: 0 };
  try {
    if (typeof navigator !== 'undefined' && navigator.gpu) {
      info.webgpu = true;
      var ad = await navigator.gpu.requestAdapter();
      if (ad) {
        try { info.f16 = !!(ad.features && ad.features.has('shader-f16')); } catch(e){}
        try { info.maxBuffer = (ad.limits && ad.limits.maxBufferSize) || 0; } catch(e){}
      }
    }
  } catch(e){}
  _uzmedGpu = info;
  return info;
}

function uzmedLS(k, d){ try { var v = localStorage.getItem(k); return (v == null || v === '') ? d : v; } catch(e){ return d; } }
function uzmedSetLS(k, v){ try { localStorage.setItem(k, v); } catch(e){} }
function uzmedLLMMode(){ var m = uzmedLS('UZMED_AI_MODE', 'both'); return (m === 'qwen' || m === 'gemma' || m === 'kb' || m === 'both') ? m : 'both'; }
function uzmedQwenId(){ var id = uzmedLS('UZMED_AI_QWEN_MODEL', UZMED_LLM_DEFAULTS.qwen); return UZMED_LLM_CATALOG[id] ? id : UZMED_LLM_DEFAULTS.qwen; }
function uzmedGemmaId(){ var id = uzmedLS('UZMED_AI_GEMMA_MODEL', UZMED_LLM_DEFAULTS.gemma); return UZMED_LLM_CATALOG[id] ? id : UZMED_LLM_DEFAULTS.gemma; }
function uzmedHaveModel(id){ return uzmedLS('UZMED_HAVE_' + id, '') === '1'; }
function uzmedWebGPUOk(){ try { return (typeof navigator !== 'undefined') && !!navigator.gpu; } catch(e){ return false; } }

function uzmedEsc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function uzmedFmtModel(s){ return formatAiText(uzmedEsc(s)); }

async function uzmedLoadMLC(){
  if (_uzmedLLM.mlc) return _uzmedLLM.mlc;
  _uzmedLLM.mlc = await import(UZMED_WEBLLM_CDN);
  return _uzmedLLM.mlc;
}

// Xatolikni odam tushunadigan oʼzbekcha sababga aylantiradi
function uzmedFriendlyErr(e){
  var m = (e && e.message) ? String(e.message) : String(e || '');
  if (/no-webgpu/i.test(m)) return 'qurilmada WebGPU yoʼq (yangiroq Chrome/Edge kerak)';
  if (/disposed|already been|destroyed|device.*lost|lost.*device/i.test(m)) return 'GPU qurilmasi uzilib qoldi — sahifani yangilang (qayta yuklang) va yana urinib koʼring';
  if (/allocation failed|out of memory|oom|cannot allocate|RangeError|buffer size|maximum/i.test(m)) return 'qurilma xotirasi yetmadi — yengilroq (0.5B yoki f16) modelni tanlang, ortiqcha ilova/varaqlarni yoping';
  if (/shader-f16|f16/i.test(m)) return 'bu (f16) model qurilmangizda qoʼllanmaydi — q4f32 variantni tanlang';
  if (/webgpu|adapter|gpu|device|destroyed/i.test(m)) return 'WebGPU xatosi — Chrome/Edge ni yangilang yoki qurilmani qayta yuklang';
  if (/network|fetch|load failed|cors|download/i.test(m)) return 'internet uzildi — model toʼliq yuklab olinmagan';
  return (m.slice(0, 90) || 'nomaʼlum xato');
}

async function uzmedEnsureModel(modelId, onProgress){
  if (!uzmedWebGPUOk()) throw new Error('no-webgpu');
  const mlc = await uzmedLoadMLC();
  const cb = onProgress || function(){};
  // Eski engine ni tashlab, butunlay yangisini yaratadi (disposed/buzilgan holatdan tiklanish)
  async function fresh(){
    try { if (_uzmedLLM.engine && _uzmedLLM.engine.unload) await _uzmedLLM.engine.unload(); } catch(_){}
    _uzmedLLM.engine = null; _uzmedLLM.current = null;
    _uzmedLLM.engine = await mlc.CreateMLCEngine(modelId, { initProgressCallback: cb }, UZMED_CHAT_OPTS);
    _uzmedLLM.current = modelId;
    return _uzmedLLM.engine;
  }
  try {
    if (!_uzmedLLM.engine) return await fresh();
    if (typeof _uzmedLLM.engine.setInitProgressCallback === 'function') _uzmedLLM.engine.setInitProgressCallback(cb);
    if (_uzmedLLM.current !== modelId) {
      await _uzmedLLM.engine.reload(modelId, UZMED_CHAT_OPTS);
      _uzmedLLM.current = modelId;
    }
    return _uzmedLLM.engine;
  } catch (e) {
    var m = (e && e.message) ? String(e.message) : '';
    // Engine disposed/destroyed/qurilma yoʼqolgan boʼlsa — yangidan yaratib koʼramiz
    if (/disposed|destroyed|device.*lost|lost.*device|invalid|already been/i.test(m)) {
      return await fresh();
    }
    // Boshqa xato (mas. xotira yetmadi) — holatni tozalab, otkazamiz
    try { if (_uzmedLLM.engine && _uzmedLLM.engine.unload) await _uzmedLLM.engine.unload(); } catch(_){}
    _uzmedLLM.engine = null; _uzmedLLM.current = null;
    throw e;
  }
}

// Barcha generatsiyalar shu yagona, disposed/qurilma-yoʼqolishiga chidamli funksiya orqali oʼtadi
async function uzmedChatComplete(modelId, messages, extra){
  async function run(){
    const eng = await uzmedEnsureModel(modelId);
    return await eng.chat.completions.create(Object.assign({ messages: messages, temperature: 0.3, max_tokens: 800, stream: false }, extra || {}));
  }
  try {
    return await run();
  } catch (e) {
    var m = (e && e.message) ? String(e.message) : '';
    if (/disposed|device.*lost|lost.*device|destroyed|invalid|already been/i.test(m)) {
      // Engine oʼlgan — tozalab, bitta toza urinish (yangidan yuklab)
      try { if (_uzmedLLM.engine && _uzmedLLM.engine.unload) await _uzmedLLM.engine.unload(); } catch(_){}
      _uzmedLLM.engine = null; _uzmedLLM.current = null;
      return await run();
    }
    throw e;
  }
}

// Model haqiqatan ishlashini tekshirish — bitta tokenlik sinov generatsiyasi
async function uzmedTestModel(modelId, onProgress){
  if (onProgress) { try { await uzmedEnsureModel(modelId, onProgress); } catch(e){ /* uzmedChatComplete ichida qayta urinadi */ } }
  const r = await uzmedChatComplete(modelId, [{ role: 'user', content: 'OK' }], { max_tokens: 1, temperature: 0 });
  return !!(r && r.choices);
}

async function uzmedGen(modelId, messages){
  const reply = await uzmedChatComplete(modelId, messages);
  return (reply && reply.choices && reply.choices[0] && reply.choices[0].message) ? reply.choices[0].message.content : '';
}

function uzmedAiMessages(text, grounding){
  var adminIns = '';
  try { if (window.uzmedGetInstruction) adminIns = window.uzmedGetInstruction(); } catch(e){}
  // Admin ko'rsatmasi bo'lsa — asosiy AI_SYSTEM ni almashtiradi (qarama-qarshi qoidalar bo'lmasin)
  var sysContent = adminIns ? adminIns : AI_SYSTEM;
  var msgs = [{ role: 'system', content: sysContent }];
  if (grounding && grounding.trim()) {
    msgs.push({ role: 'system', content: "UZMED ilovasining ICHKI tibbiy bazasidan tasdiqlangan maʼlumot. Faktlar, MKB-10 kodlari va dori dozalarini aynan shu yerdan ol va savolga moslab oʼzbek tilida sodda javob ber:\n\n" + grounding });
  }
  aiHistory.slice(-8).forEach(function(m){
    msgs.push({ role: m.role === 'model' ? 'assistant' : 'user', content: (m.parts && m.parts[0] && m.parts[0].text) ? m.parts[0].text : '' });
  });
  msgs.push({ role: 'user', content: text });
  return msgs;
}

// Ikki model javobidan sifatliroqini tanlash uchun oddiy ball
function scoreAnswer(t){
  t = String(t || '');
  var s = Math.min(t.length, 1200) / 120;
  if (/MKB|ICD|J3\d|J4\d|L\d\d|T78|K\d\d|R\d\d/i.test(t)) s += 3;
  if (/doza|mg|ml|kun|sutka/i.test(t)) s += 2;
  if (/\*\*/.test(t)) s += 1;
  if (/as an ai|language model|i'?m sorry|i cannot|kechirasiz, men/i.test(t)) s -= 4;
  return s;
}

function appendModelBotMsg(label, text, kbMatched){
  const wrap = document.getElementById('aiMessages');
  const tag = '<span style="display:inline-block;font-size:10px;font-weight:800;color:#4f46e5;background:#eef2ff;border-radius:6px;padding:2px 7px;margin-bottom:6px">' + uzmedEsc(label) + ' • oflayn AI</span>';
  const foot = '<div style="margin-top:8px;font-size:10.5px;color:var(--muted)">' + uzmedEsc(label) + (kbMatched ? ' + UZMED ichki bazasi' : ' (oflayn)') + ' asosida</div>';
  wrap.innerHTML += `
    <div class="ai-msg-row">
      <div class="ai-msg-avatar bot"><i class=uzi139></i></div>
      <div class="ai-bubble bot">${tag}<div>${uzmedFmtModel(text)}</div>${foot}</div>
    </div>
    <div class="ai-time bot">${getAiTime()}</div>`;
  wrap.scrollTop = wrap.scrollHeight;
}

function appendCombinedBotMsg(best, alt, kbMatched){
  const wrap = document.getElementById('aiMessages');
  const tag = '<span style="display:inline-block;font-size:10px;font-weight:800;color:#4f46e5;background:#eef2ff;border-radius:6px;padding:2px 7px;margin-bottom:6px">' + uzmedEsc(best.label) + ' • oflayn AI</span>';
  const altBlock = '<details style="margin-top:10px;border-top:1px dashed var(--border);padding-top:8px">'
    + '<summary style="cursor:pointer;font-size:11px;font-weight:700;color:#4f46e5">' + uzmedEsc(alt.label) + ' javobini koʼrish</summary>'
    + '<div style="margin-top:6px;font-size:13px;color:var(--text);opacity:.92">' + uzmedFmtModel(alt.text) + '</div></details>';
  const foot = '<div style="margin-top:8px;font-size:10.5px;color:var(--muted)">Qwen + Gemma' + (kbMatched ? ' + UZMED ichki bazasi' : '') + ' asosida</div>';
  wrap.innerHTML += `
    <div class="ai-msg-row">
      <div class="ai-msg-avatar bot"><i class=uzi139></i></div>
      <div class="ai-bubble bot">${tag}<div>${uzmedFmtModel(best.text)}</div>${altBlock}${foot}</div>
    </div>
    <div class="ai-time bot">${getAiTime()}</div>`;
  wrap.scrollTop = wrap.scrollHeight;
}

function uzmedRefreshEngineBadge(){
  var dot = document.getElementById('aiEngineDot');
  var txt = document.getElementById('aiEngineTxt');
  if (!txt || !dot) return;
  var mode = uzmedLLMMode();
  var ready = [];
  if ((mode === 'both' || mode === 'qwen') && uzmedHaveModel(uzmedQwenId())) ready.push('Qwen');
  if ((mode === 'both' || mode === 'gemma') && uzmedHaveModel(uzmedGemmaId())) ready.push('Gemma');
  if (typeof uzmedCloudEnabled === 'function' && uzmedCloudEnabled()) {
    dot.style.background = '#22c55e'; txt.textContent = 'Gemini • bulutli AI';
  } else if (mode === 'kb') {
    dot.style.background = '#22c55e'; txt.textContent = 'Ichki baza';
  } else if (!uzmedWebGPUOk()) {
    dot.style.background = '#f59e0b'; txt.textContent = 'Ichki baza (WebGPU yoʼq)';
  } else if (ready.length) {
    dot.style.background = '#22c55e'; txt.textContent = ready.join(' + ') + ' • oflayn AI';
  } else {
    dot.style.background = '#f59e0b'; txt.textContent = 'Ichki baza • modelni yuklang';
  }
}

window.uzmedDownloadModel = async function(fam){
  var sel = document.getElementById('llmSel_' + fam);
  var bar = document.getElementById('dlBar_' + fam);
  var txt = document.getElementById('dlTxt_' + fam);
  var btn = document.getElementById('dlBtn_' + fam);
  if (!sel) return;
  var id = sel.value;
  if (!uzmedWebGPUOk()) { if (txt) txt.innerHTML = 'Bu qurilma WebGPU-ni qoʼllamaydi — ichki baza ishlaydi.'; return; }
  // f16 model tanlangan, lekin qurilma shader-f16 ni qoʼllamasa — ogohlantirish
  var meta = UZMED_LLM_CATALOG[id] || {};
  var gpu = await uzmedGpuProbe();
  if (meta.f16 && !gpu.f16) {
    if (txt) txt.innerHTML = '⚠ Bu (f16) model qurilmangizda ishlamaydi (shader-f16 yoʼq). Iltimos, f16-siz (q4f32) variantni tanlang.';
    return;
  }
  uzmedSetLS(fam === 'qwen' ? 'UZMED_AI_QWEN_MODEL' : 'UZMED_AI_GEMMA_MODEL', id);
  if (btn) { btn.disabled = true; btn.style.opacity = '.6'; }
  if (txt) txt.innerHTML = 'Tayyorlanmoqda...';
  try {
    await uzmedEnsureModel(id, function(p){
      var pct = (p && typeof p.progress === 'number') ? Math.round(p.progress * 100) : null;
      if (bar && pct != null) bar.style.width = pct + '%';
      if (txt) txt.innerHTML = (p && p.text) ? uzmedEsc(p.text) : (pct != null ? pct + '%' : 'Yuklanmoqda...');
    });
    // Yuklab olingach — haqiqatan ishlashini sinab koʼramiz (xotira yetadimi?)
    if (bar) bar.style.width = '100%';
    if (txt) txt.innerHTML = 'Sinovdan oʼtkazilmoqda…';
    await uzmedTestModel(id);
    uzmedSetLS('UZMED_HAVE_' + id, '1');
    // Edge Gallery uslubi: yuklab olgach model avtomatik faollashadi (AI oʼchiq boʼlsa yoqamiz)
    if (uzmedLLMMode() === 'kb') {
      uzmedSetLS('UZMED_AI_MODE', fam);
      var rMode = document.querySelector('input[name="uzmedAiMode"][value="' + fam + '"]');
      if (rMode) { rMode.checked = true; if (typeof window.uzmedAiModeHi === 'function') window.uzmedAiModeHi(); }
    }
    if (txt) txt.innerHTML = 'Tayyor ✓ — sinovdan oʼtdi. Chatda avtomatik ishlaydi.';
  } catch (e) {
    if (bar) bar.style.width = '0%';
    uzmedSetLS('UZMED_HAVE_' + id, '');   // sinovdan oʼtmadi — "yuklangan" deb belgilamaymiz
    var msg = (e && e.message) ? String(e.message) : 'xato';
    var lightest = (fam === 'qwen') ? 'Qwen 2.5 — 0.5B' : 'Gemma 2 — 2B (1k)';
    if (/allocation failed|out of memory|oom|cannot allocate|RangeError|buffer size|maximum/i.test(msg)) {
      // Xotira yetishmovchiligi — eng kichik modelni tavsiya qilamiz
      if (txt) txt.innerHTML = '⚠ <b>Xotira yetmadi</b> — model bu qurilmada ishga tushmadi. Ochiq ilova/varaqlarni yoping va <b>' + lightest + '</b>' + (gpu.f16 ? ' yoki <b>f16</b>' : '') + ' variantini tanlang. Ichki baza esa ishlayveradi.';
      // Avtomatik eng yengil modelga oʼtkazib qoʼyamiz
      var lightId = (fam === 'qwen') ? (gpu.f16 ? 'Qwen2.5-0.5B-Instruct-q4f16_1-MLC' : 'Qwen2.5-0.5B-Instruct-q4f32_1-MLC') : (gpu.f16 ? 'gemma-2-2b-it-q4f16_1-MLC-1k' : 'gemma-2-2b-it-q4f32_1-MLC-1k');
      if (sel && sel.value !== lightId) { sel.value = lightId; uzmedSetLS(fam === 'qwen' ? 'UZMED_AI_QWEN_MODEL' : 'UZMED_AI_GEMMA_MODEL', lightId); }
    } else {
      if (txt) txt.innerHTML = '⚠ Yuklab boʼlmadi: ' + uzmedEsc(uzmedFriendlyErr(e)) + '. Ichki baza ishlayveradi.';
    }
  }
  if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
  uzmedRefreshEngineBadge();
};

function uzmedModelOptions(fam, selectedId){
  var html = '';
  for (var id in UZMED_LLM_CATALOG) {
    if (UZMED_LLM_CATALOG[id].fam !== fam) continue;
    var m = UZMED_LLM_CATALOG[id];
    var have = uzmedHaveModel(id) ? ' ✓' : '';
    html += '<option value="' + id + '"' + (id === selectedId ? ' selected' : '') + ' style="background:#1a2742;color:#eef2fb">' + m.label + ' · ' + m.size + have + '</option>';
  }
  return html;
}

function uzmedModelCard(fam, title, selId){
  var have = uzmedHaveModel(selId);
  return ''
    + '<div style="border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:13px;margin-bottom:11px;background:rgba(255,255,255,.04)">'
    +   '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px">'
    +     '<div style="font-size:13.5px;font-weight:800;color:#eef2fb">' + title + '</div>'
    +     '<div style="flex:0 0 auto;font-size:10px;font-weight:800;letter-spacing:.2px;padding:3px 9px;border-radius:999px;color:' + (have ? '#34d399' : '#aeb9d4') + ';background:' + (have ? 'rgba(16,185,129,.15)' : 'rgba(255,255,255,.06)') + ';border:1px solid ' + (have ? 'rgba(16,185,129,.32)' : 'rgba(255,255,255,.10)') + '">' + (have ? 'YUKLANGAN ✓' : 'YUKLANMAGAN') + '</div>'
    +   '</div>'
    +   '<select id="llmSel_' + fam + '" style="width:100%;padding:10px 11px;border:1px solid rgba(255,255,255,.14);border-radius:10px;font-size:12.5px;font-weight:600;color:#eef2fb;background:#1a2742;margin-bottom:10px;cursor:pointer;-webkit-appearance:none;appearance:none">' + uzmedModelOptions(fam, selId) + '</select>'
    +   '<div style="height:8px;background:rgba(255,255,255,.10);border-radius:6px;overflow:hidden;margin-bottom:9px"><div id="dlBar_' + fam + '" style="height:100%;width:' + (have ? '100' : '0') + '%;background:linear-gradient(90deg,#3b82f6,#6366f1);transition:width .2s"></div></div>'
    +   '<div style="display:flex;align-items:center;gap:10px">'
    +     '<button id="dlBtn_' + fam + '" onclick="uzmedDownloadModel(\'' + fam + '\')" style="flex:0 0 auto;padding:9px 16px;border:none;border-radius:10px;background:linear-gradient(135deg,#3b82f6,#6366f1);color:#fff;font-size:12px;font-weight:800;cursor:pointer;box-shadow:0 4px 14px rgba(59,130,246,.35)">' + (have ? 'Qayta yuklash' : 'Yuklab olish') + '</button>'
    +     '<div id="dlTxt_' + fam + '" style="font-size:11px;line-height:1.45;color:#aeb9d4;flex:1;min-width:0">' + (have ? 'Tayyor — internetsiz ishlaydi.' : 'Bir marta yuklab olish kerak.') + '</div>'
    +   '</div>'
    + '</div>';
}

window.uzmedAiModeHi = function(){
  ['both','qwen','gemma','kb'].forEach(function(v){
    var sel = document.querySelector('input[name="uzmedAiMode"][value="' + v + '"]');
    var lab = document.getElementById('aimode_' + v);
    if (!sel || !lab) return;
    var on = sel.checked;
    lab.style.borderColor = on ? '#6366f1' : 'rgba(255,255,255,.12)';
    lab.style.background  = on ? 'rgba(99,102,241,.18)' : 'rgba(255,255,255,.04)';
  });
};

window.aiSettingsOpen = function(){
  var ex = document.getElementById('aiSettingsModal');
  if (ex) ex.remove();
  var mode = uzmedLLMMode();
  var gpu = uzmedWebGPUOk();
  function rc(v, lbl){ var on = (mode === v); return '<label id="aimode_' + v + '" style="display:flex;align-items:center;gap:10px;padding:11px 13px;border:1.5px solid ' + (on ? '#6366f1' : 'rgba(255,255,255,.12)') + ';border-radius:11px;cursor:pointer;font-size:13px;font-weight:600;color:#eef2fb;background:' + (on ? 'rgba(99,102,241,.18)' : 'rgba(255,255,255,.04)') + ';transition:.15s"><input type="radio" name="uzmedAiMode" value="' + v + '"' + (on ? ' checked' : '') + ' onchange="uzmedAiModeHi()" style="accent-color:#6366f1;width:16px;height:16px;flex:0 0 auto">' + lbl + '</label>'; }
  var gpuNote = gpu
    ? '<div style="font-size:11.5px;color:#34d399;font-weight:600;line-height:1.5;background:rgba(16,185,129,.13);border:1px solid rgba(16,185,129,.28);border-radius:11px;padding:10px 12px">✓ Qurilma qoʼllab-quvvatlaydi (WebGPU). Model bir marta yuklansa, internetsiz ishlaydi.</div>'
    : '<div style="font-size:11.5px;color:#fbbf24;font-weight:600;line-height:1.5;background:rgba(245,158,11,.13);border:1px solid rgba(245,158,11,.28);border-radius:11px;padding:10px 12px">⚠ Bu qurilma/brauzer WebGPU-ni qoʼllamaydi. UZMED ichki bazasi internetsiz ishlayveradi; AI modellari uchun yangiroq qurilma yoki Chrome kerak.</div>';
  var cloudOn = uzmedCloudEnabled();
  var cloudKey = '';
  try { cloudKey = String(localStorage.getItem('UZMED_GEMINI_KEY') || '').trim(); } catch(e){}
  if (!cloudKey) cloudKey = UZMED_DEFAULT_GEMINI_KEY;
  var cloudSection = ''
    + '<div style="border:1px solid rgba(99,102,241,.35);border-radius:14px;padding:14px;margin-bottom:16px;background:rgba(99,102,241,.10)">'
    +   '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px">'
    +     '<div style="font-size:13.5px;font-weight:800;color:#eef2fb">☁ Bulutli AI (Gemini)</div>'
    +     '<label style="display:flex;align-items:center;gap:7px;font-size:11.5px;font-weight:700;color:' + (cloudOn ? '#34d399' : '#aeb9d4') + ';cursor:pointer" id="cloudToggleLbl"><input type="checkbox" id="cloudToggle"' + (cloudOn ? ' checked' : '') + ' onchange="uzmedCloudToggle()" style="accent-color:#6366f1;width:16px;height:16px"> ' + (cloudOn ? 'Yoqilgan' : 'Oʼchirilgan') + '</label>'
    +   '</div>'
    +   '<div style="font-size:11px;color:#aeb9d4;line-height:1.5;margin-bottom:9px">Internet boʼlsa, savollar Google Gemini orqali javob oladi (eng sifatli). Internet yoʼq boʼlsa, quyidagi oflayn model yoki ichki baza ishlaydi.</div>'
    +   '<div style="font-size:10px;font-weight:800;letter-spacing:.3px;text-transform:uppercase;color:#7e89a8;margin-bottom:6px">API kalit</div>'
    +   '<div style="display:flex;gap:8px">'
    +     '<input id="cloudKeyInput" type="password" value="' + uzmedEsc(cloudKey) + '" placeholder="API kalitni kiriting" style="flex:1;min-width:0;padding:9px 11px;border:1px solid rgba(255,255,255,.14);border-radius:10px;font-size:12px;color:#eef2fb;background:#1a2742;font-family:monospace">'
    +     '<button onclick="uzmedCloudKeySave()" style="flex:0 0 auto;padding:9px 14px;border:none;border-radius:10px;background:linear-gradient(135deg,#3b82f6,#6366f1);color:#fff;font-size:12px;font-weight:800;cursor:pointer">Saqlash</button>'
    +   '</div>'
    +   '<div id="cloudKeyMsg" style="font-size:10.5px;color:#7e89a8;line-height:1.45;margin-top:7px">Kalit shu qurilmada saqlanadi.</div>'
    + '</div>';
  var html = ''
    + '<div style="position:absolute;inset:0;background:rgba(2,6,23,.62);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px)" onclick="aiSettingsClose()"></div>'
    + '<div style="position:relative;width:min(440px,94vw);max-height:90vh;overflow-y:auto;overflow-x:hidden;background:linear-gradient(180deg,#1b2848 0%,#131e36 100%);border:1px solid rgba(255,255,255,.12);border-radius:20px;padding:20px;box-shadow:0 30px 70px rgba(0,0,0,.55)">'
    +   '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:5px">'
    +     '<div style="font-size:17px;font-weight:900;color:#fff;letter-spacing:-.3px">AI sozlamalari</div>'
    +     '<button onclick="aiSettingsClose()" style="flex:0 0 auto;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.07);width:32px;height:32px;border-radius:9px;font-size:18px;line-height:1;cursor:pointer;color:#aeb9d4">×</button>'
    +   '</div>'
    +   '<div style="font-size:11.5px;color:#aeb9d4;line-height:1.55;margin-bottom:14px">Bulutli AI (internet) yoki oflayn modellar (qurilma ichida). Internet boʼlmasa, ilova ichki tibbiy bazadan javob beradi.</div>'
    +   cloudSection
    +   '<div style="font-size:11px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;color:#7e89a8;margin-bottom:9px">Oflayn modellar (internetsiz)</div>'
    +   '<div style="margin-bottom:10px">' + gpuNote + '</div>'
    +   '<div id="aiGpuLine" style="font-size:10.5px;color:#7e89a8;line-height:1.5;margin-bottom:16px">Qurilma imkoniyatlari tekshirilmoqda…</div>'
    +   '<div style="font-size:11px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;color:#7e89a8;margin-bottom:9px">Javob rejimi</div>'
    +   '<div style="display:grid;gap:8px;margin-bottom:18px">'
    +     rc('both', 'Qwen + Gemma birga (tavsiya)') + rc('qwen', 'Faqat Qwen') + rc('gemma', 'Faqat Gemma') + rc('kb', 'Faqat UZMED ichki bazasi (AI-siz)')
    +   '</div>'
    +   '<div style="font-size:11px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;color:#7e89a8;margin-bottom:9px">Modellar</div>'
    +   uzmedModelCard('qwen', 'Qwen 2.5', uzmedQwenId())
    +   uzmedModelCard('gemma', 'Gemma 2', uzmedGemmaId())
    +   '<div style="font-size:10.5px;color:#7e89a8;line-height:1.55;margin-top:4px">Model fayllari brauzer keshida saqlanadi. Bir marta yuklab olgach, ilova internetsiz javob beradi. Telefonda 1.5–2 GB boʼsh joy tavsiya etiladi.</div>'
    +   '<button onclick="aiSettingsSave()" style="width:100%;margin-top:16px;padding:13px;border:none;border-radius:13px;background:linear-gradient(135deg,#3b82f6,#6366f1);color:#fff;font-size:14px;font-weight:800;cursor:pointer;box-shadow:0 8px 22px rgba(59,130,246,.4)">Saqlash</button>'
    + '</div>';
  var modal = document.createElement('div');
  modal.id = 'aiSettingsModal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px';
  modal.innerHTML = html;
  document.body.appendChild(modal);
  // Qurilma imkoniyatlarini aniqlab, tavsiya koʼrsatamiz
  uzmedGpuProbe().then(function(g){
    var el = document.getElementById('aiGpuLine');
    if (!el) return;
    if (!g.webgpu) { el.innerHTML = 'Qurilmangiz WebGPU-ni qoʼllamaydi — AI modellari ishlamaydi, ammo UZMED ichki bazasi internetsiz javob beradi.'; return; }
    var gb = g.maxBuffer ? (g.maxBuffer / (1024*1024*1024)) : 0;
    var memTxt = gb ? ('bitta blok ≈ ' + gb.toFixed(1) + ' GB') : 'xotira nomaʼlum';
    el.innerHTML = 'Qurilma: WebGPU ✓ · shader-f16 ' + (g.f16 ? '✓ (f16 modellar ishlaydi — kam xotira)' : '✗ (faqat q4f32 variantlar)') + ' · ' + memTxt + '. '
      + (gb && gb < 1 ? '<b style="color:#fbbf24">Xotira kam — eng yengil modelni tanlang.</b>' : 'Tavsiya: avval eng yengil modelni sinab koʼring.');
    // f16 qoʼllab-quvvatlansa va hali model yuklanmagan boʼlsa — eng yengil f16 ni tanlab qoʼyamiz
    if (g.f16) {
      var qSel = document.getElementById('llmSel_qwen');
      var gSel = document.getElementById('llmSel_gemma');
      if (qSel && !uzmedHaveModel(uzmedQwenId()) && qSel.querySelector('option[value="Qwen2.5-0.5B-Instruct-q4f16_1-MLC"]')) qSel.value = 'Qwen2.5-0.5B-Instruct-q4f16_1-MLC';
      if (gSel && !uzmedHaveModel(uzmedGemmaId()) && gSel.querySelector('option[value="gemma-2-2b-it-q4f16_1-MLC-1k"]')) gSel.value = 'gemma-2-2b-it-q4f16_1-MLC-1k';
    }
  });
};

window.aiSettingsClose = function(){ var m = document.getElementById('aiSettingsModal'); if (m) m.remove(); };

window.uzmedCloudToggle = function(){
  var cb = document.getElementById('cloudToggle');
  var lbl = document.getElementById('cloudToggleLbl');
  var on = cb && cb.checked;
  uzmedSetLS('UZMED_CLOUD_AI', on ? '1' : '0');
  if (lbl) { lbl.style.color = on ? '#34d399' : '#aeb9d4'; lbl.lastChild.textContent = on ? ' Yoqilgan' : ' Oʼchirilgan'; }
  if (typeof uzmedRefreshEngineBadge === 'function') uzmedRefreshEngineBadge();
};

window.uzmedCloudKeySave = function(){
  var inp = document.getElementById('cloudKeyInput');
  var msg = document.getElementById('cloudKeyMsg');
  if (!inp) return;
  var k = String(inp.value || '').trim();
  uzmedSetLS('UZMED_GEMINI_KEY', k);
  try { if (window.APP_DB && APP_DB.settings) { APP_DB.settings.apiKey = k; if (APP_DB.save) APP_DB.save(); } } catch(e){}
  if (msg) { msg.style.color = '#34d399'; msg.textContent = '✓ Kalit saqlandi. Endi chatda bulutli AI ishlaydi.'; }
  if (typeof uzmedRefreshEngineBadge === 'function') uzmedRefreshEngineBadge();
};

window.aiSettingsSave = function(){
  var sel = document.querySelector('input[name="uzmedAiMode"]:checked');
  if (sel) uzmedSetLS('UZMED_AI_MODE', sel.value);
  var q = document.getElementById('llmSel_qwen');
  var g = document.getElementById('llmSel_gemma');
  if (q) uzmedSetLS('UZMED_AI_QWEN_MODEL', q.value);
  if (g) uzmedSetLS('UZMED_AI_GEMMA_MODEL', g.value);
  uzmedRefreshEngineBadge();
  aiSettingsClose();
};

try {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', uzmedRefreshEngineBadge);
  else uzmedRefreshEngineBadge();
  window.addEventListener('online', uzmedRefreshEngineBadge);
  window.addEventListener('offline', uzmedRefreshEngineBadge);
} catch(e){}

// Oflayn AI (Qwen/Gemma) javobi — model yuklangan boʼlsa ishlatadi.
// ════════════════════════════════════════════════════════════════════════════
//  BULUTLI AI — Google Gemini API (internet boʼlsa, eng sifatli javob)
//  Kalit Sozlamalardan yoki localStorage dan olinadi; standart kalit quyida.
// ════════════════════════════════════════════════════════════════════════════
const UZMED_DEFAULT_GEMINI_KEY = '';
// Tartib bilan sinaladigan modellar — bepul kvotasi kattaroqlari birinchi
const UZMED_GEMINI_MODELS = ['gemini-2.0-flash', 'gemini-2.0-flash-lite', 'gemini-2.5-flash-lite', 'gemini-2.5-flash', 'gemini-flash-latest'];

function uzmedGeminiKey(){
  try { var k = String(localStorage.getItem('UZMED_GEMINI_KEY') || '').trim(); if (k) return k; } catch(e){}
  try { if (window.APP_DB && APP_DB.settings && APP_DB.settings.apiKey) { var s = String(APP_DB.settings.apiKey).trim(); if (s) return s; } } catch(e){}
  return UZMED_DEFAULT_GEMINI_KEY;
}
function uzmedCloudEnabled(){
  // Kalit bor va foydalanuvchi oʼchirib qoʼymagan boʼlsa — yoqilgan
  if (uzmedLS('UZMED_CLOUD_AI', '1') === '0') return false;
  return !!uzmedGeminiKey();
}
window.uzmedGeminiKey = uzmedGeminiKey;
window.uzmedCloudEnabled = uzmedCloudEnabled;

// ── Dori nomini suhbatdan topib, UZMED bazasidagi to'liq ma'lumotni grounding qiladi ──
var _uzmedDrugIndex = null;
function uzmedDrugIndexBuild() {
  if (_uzmedDrugIndex) return _uzmedDrugIndex;
  var idx = [];
  try {
    var arr = (window.APP_DB && APP_DB.drugs) || [];
    arr.forEach(function (d) {
      if (!d || !d.name) return;
      // har bir dori nomi (qavs ichidagi variantlar ham)
      var names = [];
      String(d.name).split(/[\/,()]+/).forEach(function (p) { p = p.trim().toLowerCase(); if (p.length >= 4) names.push(p); });
      idx.push({ d: d, names: names });
    });
  } catch (e) {}
  _uzmedDrugIndex = idx;
  return idx;
}
function uzmedFmtDrug(d) {
  var L = [];
  L.push('**' + d.name + '**');
  if (d.inn) L.push('INN: ' + d.inn);
  if (d.guruh) L.push('Guruhi: ' + d.guruh);
  if (d.atx) L.push('ATC kodi: ' + d.atx);
  if (d.shakl) L.push('Shakl: ' + d.shakl);
  if (d.korsatmalar) L.push('Ko\'rsatmalar (qaysi kasalliklarda): ' + d.korsatmalar);
  if (d.dozalash) L.push('Dozalash: ' + d.dozalash);
  if (d.qarshi) L.push('Qarshi ko\'rsatmalar: ' + d.qarshi);
  if (d.yon) L.push('Yon ta\'sirlari: ' + d.yon);
  if (d.eslatma) L.push('Eslatma: ' + d.eslatma);
  return L.join('\n');
}
// text + so'nggi suhbat tarixidan dori nomlarini qidiradi
function uzmedDrugGrounding(text) {
  try {
    var idx = uzmedDrugIndexBuild();
    if (!idx.length) return '';
    // Tarix alohida messages orqali beriladi; manba qidiruvi joriy savolga tegishli.
    var normalize = window.UZMED_REFERENCE_SEARCH && window.UZMED_REFERENCE_SEARCH.normalize;
    var hay = ' ' + (normalize ? normalize(text) : String(text || '').toLowerCase()) + ' ';
    var found = [], seen = {};
    for (var i = 0; i < idx.length && found.length < 2; i++) {
      var names = idx[i].names;
      for (var j = 0; j < names.length; j++) {
        var nm = normalize ? normalize(names[j]) : names[j];
        // so'z chegarasi bilan moslik
        var re = new RegExp('(^|[^a-zа-яё])' + nm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-zа-яё]|$)', 'i');
        if (re.test(hay) && !seen[idx[i].d.name]) { seen[idx[i].d.name] = 1; found.push(idx[i].d); break; }
      }
    }
    if (!found.length) return '';
    return '[UZMED DORI BAZASI — joriy savolga mos ichki yozuvlar. Ularning manba va versiyasini hisobga oling; faqat so‘ralgan ma’lumotni ishlating:]\n' + found.map(uzmedFmtDrug).join('\n\n');
  } catch (e) { return ''; }
}
window.uzmedDrugGrounding = uzmedDrugGrounding;

// Gemini'ga soʼrov. Qaytaradi: { answered:bool, text, kbMatched } yoki xato otadi.
async function uzmedCloudAnswer(text){
  var key = uzmedGeminiKey();
  if (!key) return { answered: false, error: new Error('no-key') };
  // Ichki bazadan grounding — faqat YORDAMCHI maʼlumot sifatida (majburlamaymiz)
  var local = '';
  try { local = localUzmedAiAnswer(text) || ''; } catch(e){}
  var kbMatched = local && !/^Savolingiz bo/.test(String(local));
  // Foydalanuvchi yuklagan hujjatlardan mos parchalar
  var docG = '';
  try { if (window.uzmedDocs) docG = await window.uzmedDocs.grounding(text); } catch(e){}
  // Suhbatda eslatilgan dori(lar) — UZMED bazasidan aniq ma'lumot
  var drugG = '';
  try { drugG = uzmedDrugGrounding(text); } catch(e){}
  // Admin tomonidan kiritilgan global ko'rsatma (system prompt) — agar bo'lsa, asosiy promptni TO'LIQ almashtiradi
  var adminIns = '';
  try { if (window.uzmedGetInstruction) adminIns = window.uzmedGetInstruction(); } catch(e){}
  var sys;
  if (adminIns) {
    // Admin to'liq nazoratda — ortiqcha "to'liq tushuntir" yoki ogohlantirish qoidalarini qo'shmaymiz
    sys = adminIns
      + (drugG ? ('\n\n' + drugG) : '')
      + (docG ? ('\n\n' + docG) : '')
      + (kbMatched ? ('\n\n[UZMED ichki bazasidan SHA YORDAMCHI havola (savolga aloqasiz boʼlishi mumkin — agar mos kelmasa, ETIBOR BERMA):]\n' + String(local).slice(0, 1500)) : '');
  } else {
    sys = AI_SYSTEM
      + (drugG ? ('\n\n' + drugG) : '')
      + (docG ? ('\n\n' + docG + '\n[Agar yuqoridagi yuklangan hujjat savolga tegishli boʼlsa, undagi maʼlumotga ustunlik ber.]') : '')
      + (kbMatched ? ('\n\n[UZMED ichki bazasidan SHA YORDAMCHI havola (savolga aloqasiz boʼlishi mumkin — agar mos kelmasa, ETIBOR BERMA va savolga oʼzing toʼliq, mustaqil javob ber):]\n' + String(local).slice(0, 1500)) : '')
      + '\n\n[MUHIM: Avvalo foydalanuvchi savolini diqqat bilan tushun. Suhbat tarixini hisobga ol — oldingi savollarda aytilgan dori yoki kasallik nomini eslab qol va "qaysi dorini nazarda tutyapsiz?" kabi qayta soʼrama. Aynan SHU savolga toʼliq, tushunarli, tartibli oʼzbek tilida javob ber.]';
  }
  // aiHistory allaqachon Gemini formatida (role: user/model, parts:[{text}])
  var hist = (window.aiHistory || []).slice(-10).map(function(m){
    return { role: (m.role === 'model' ? 'model' : 'user'), parts: [{ text: (m.parts && m.parts[0] && m.parts[0].text) || '' }] };
  }).filter(function(m){ return m.parts[0].text; });
  if (!hist.length) hist = [{ role: 'user', parts: [{ text: text }] }];
  var body = {
    contents: hist,
    systemInstruction: { parts: [{ text: sys }] },
    generationConfig: { temperature: 0.4, maxOutputTokens: 8192, topP: 0.95, thinkingConfig: { thinkingBudget: 0 } }
  };
  var lastErr = null;
  // Har bir modelni navbat bilan sinaymiz; band (503/429/500) boʼlsa keyingisiga oʼtamiz.
  // Hammasi band boʼlsa — qisqa kutib, yana bir marta toʼliq aylanamiz.
  function isBusy(status, body){
    return status === 404 || status === 503 || status === 500 || status === 502 || status === 429
      || /overloaded|high demand|unavailable|try again|RESOURCE_EXHAUSTED/i.test(body || '');
  }
  for (var attempt = 0; attempt < 2; attempt++) {
    for (var i = 0; i < UZMED_GEMINI_MODELS.length; i++) {
      body.generationConfig.thinkingConfig.thinkingBudget = (UZMED_GEMINI_MODELS[i].indexOf('2.5') >= 0) ? 2048 : 0; var url = (window.uzmedAiEndpoint ? window.uzmedAiEndpoint(UZMED_GEMINI_MODELS[i], key) : ('https://generativelanguage.googleapis.com/v1beta/models/' + UZMED_GEMINI_MODELS[i] + ':generateContent?key=' + encodeURIComponent(key)));
      try {
        var r = await (window.uzmedAiFetch ? window.uzmedAiFetch(url, body) : fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }));
        var t = await r.text();
        if (!r.ok) {
          lastErr = new Error('HTTP ' + r.status + ' — ' + t.slice(0, 300));
          if (isBusy(r.status, t)) continue;   // band/topilmadi → keyingi model
          throw lastErr;                         // haqiqiy xato (kalit/ruxsat) → toʼxtaymiz
        }
        var j = JSON.parse(t);
        if (j.promptFeedback && j.promptFeedback.blockReason) throw new Error('bloklandi: ' + j.promptFeedback.blockReason);
        var cand = j.candidates && j.candidates[0];
        var out = (cand && cand.content && cand.content.parts ? cand.content.parts : []).map(function(p){ return p.text || ''; }).join('').trim();
        if (!out) { lastErr = new Error('boʼsh javob'); continue; }
        return { answered: true, text: out, kbMatched: kbMatched };
      } catch (e) {
        lastErr = e;
        var em = String(e && e.message || '');
        if (/HTTP (404|503|500|502|429)|overloaded|high demand|boʼsh javob/i.test(em)) continue; // boshqa modelni sinash
        throw e; // tarmoq yoki kalit xatosi
      }
    }
    // Birinchi aylanishda hammasi band boʼlsa — 1.2s kutib, yana urinamiz
    if (attempt === 0) { await new Promise(function(res){ setTimeout(res, 1200); }); }
  }
  throw (lastErr || new Error('javob yoʼq'));
}
window.uzmedCloudAnswer = uzmedCloudAnswer;

// Gemini xatosini odam tushunadigan oʼzbekcha sababga aylantiradi
function uzmedCloudFriendlyErr(e){
  var m = (e && e.message) ? String(e.message) : String(e || '');
  if (/no-key/i.test(m)) return 'API kalit kiritilmagan — Sozlamalar → AI API Key.';
  if (/HTTP 400|API key not valid|invalid.*key|API_KEY_INVALID/i.test(m)) return 'API kalit notoʼgʼri yoki Gemini API yoqilmagan (400). Kalitni tekshiring.';
  if (/HTTP 401|HTTP 403|PERMISSION_DENIED|unauthor/i.test(m)) return 'API kalit qabul qilinmadi (401/403). Kalit bekor qilingan yoki ruxsat yoʼq.';
  if (/HTTP 429|quota|rate limit|RESOURCE_EXHAUSTED/i.test(m)) return 'Limit tugadi (429). Biroz kutib qayta urinib koʼring yoki billing yoqing.';
  if (/HTTP 503|HTTP 500|HTTP 502|overloaded|high demand|unavailable/i.test(m)) return 'Gemini serverlari hozir band (503). Bir necha soniyadan soʼng qayta yuboring.';
  if (/HTTP 404/i.test(m)) return 'Model topilmadi (404) — kalit bu modelga ruxsat bermaydi.';
  if (/bloklandi|blockReason|SAFETY/i.test(m)) return 'Javob xavfsizlik filtri tomonidan bloklandi.';
  if (/timeout|abort|the operation was aborted|signal is aborted/i.test(m)) return 'Javob juda uzoq kutildi (timeout). Internetni tekshiring va qayta yuboring.';
  if (/failed to fetch|networkerror|load failed|cors/i.test(m)) return 'Internetga ulanib boʼlmadi (offline yoki CORS).';
  return (m.slice(0, 120) || 'nomaʼlum xato');
}
window.uzmedCloudFriendlyErr = uzmedCloudFriendlyErr;

// Oflayn AI (Qwen/Gemma) javobi. Qaytaradi: { modelAnswered, text, local, attempted, error }
async function uzmedOfflineAnswer(text){
  const local = localUzmedAiAnswer(text);
  const kbMatched = !/^Savolingiz bo/.test(String(local || ''));
  let grounding = kbMatched ? local : '';
  try { var dg0 = uzmedDrugGrounding(text); if (dg0) grounding = dg0 + (grounding ? '\n\n' + grounding : ''); } catch (e) {}
  try { if (window.uzmedDocs) { const dg = await window.uzmedDocs.grounding(text); if (dg) grounding = (grounding ? grounding + '\n\n' : '') + dg; } } catch (e) {}
  const mode = uzmedLLMMode();
  const ids = [];
  if (mode === 'qwen') ids.push(['Qwen', uzmedQwenId()]);
  else if (mode === 'gemma') ids.push(['Gemma', uzmedGemmaId()]);
  else if (mode === 'both') { ids.push(['Qwen', uzmedQwenId()]); ids.push(['Gemma', uzmedGemmaId()]); }
  let llmAnswers = [];
  let attempted = false, lastErr = null;
  if (mode !== 'kb' && uzmedWebGPUOk()) {
    const messages = uzmedAiMessages(text, grounding);
    for (let i = 0; i < ids.length; i++) {
      const label = ids[i][0], id = ids[i][1];
      if (!uzmedHaveModel(id)) continue;
      attempted = true;
      try {
        const t = await uzmedGen(id, messages);
        if (t && t.trim()) llmAnswers.push({ label: label, text: t.trim() });
      } catch (e) { lastErr = e; }
    }
  }
  if (llmAnswers.length >= 2) {
    llmAnswers.sort(function(a, b){ return scoreAnswer(b.text) - scoreAnswer(a.text); });
    appendCombinedBotMsg(llmAnswers[0], llmAnswers[1], kbMatched);
    return { modelAnswered: true, text: llmAnswers[0].text, local: local, attempted: attempted, error: lastErr };
  }
  if (llmAnswers.length === 1) {
    appendModelBotMsg(llmAnswers[0].label, llmAnswers[0].text, kbMatched);
    return { modelAnswered: true, text: llmAnswers[0].text, local: local, attempted: attempted, error: lastErr };
  }
  return { modelAnswered: false, text: '', local: local, attempted: attempted, error: lastErr };
}
window.uzmedOfflineAnswer = uzmedOfflineAnswer;

async function sendAiMessage() {
  if (aiTyping) return;
  const input = document.getElementById('aiInput');
  const text = input.value.trim();
  if (!text) return;

  input.value = '';
  input.style.height = 'auto';
  document.getElementById('aiSendBtn').disabled = true;
  aiTyping = true;

  appendUserMsg(text);
  aiHistory.push({ role: 'user', parts: [{ text }] });

  // UZMED Derma AI: same atlas/search backend for website and Telegram.
  if (window.UzmedDermaMedia && window.UzmedDermaMedia.isImageQuestion(text)) {
    showTyping();
    try {
      var dermaResult=await window.UzmedDermaMedia.find(text);
      hideTyping();
      appendBotMsg(dermaResult.images.length ?
        'Dermatologiya atlasidan mos rasmlar topildi.' :
        'Mos klinik rasm topilmadi. Kasallik nomini aniqroq yozing.');
      window.UzmedDermaMedia.display(dermaResult);
      aiHistory.push({role:'model',parts:[{text:'Dermatologiya rasmlari: '+(dermaResult.query||'aniqlanmadi')}]});
    } catch (_dermaError) {
      hideTyping();
      appendBotMsg('Hozir dermatologiya rasmlari olinmadi. Birozdan keyin qayta urinib ko‘ring.');
    } finally {
      aiTyping=false;
      document.getElementById('aiSendBtn').disabled=false;
    }
    return;
  }

  showTyping();

  try {
    // ── OFLAYN AI: qurilma ichida Qwen + Gemma (WebLLM), UZMED ichki bazasi grounding/fallback ──
    const local = localUzmedAiAnswer(text);
    const kbMatched = !/^Savolingiz bo/.test(String(local || ''));
    const grounding = kbMatched ? local : '';
    const mode = uzmedLLMMode();

    const ids = [];
    if (mode === 'qwen') ids.push(['Qwen', uzmedQwenId()]);
    else if (mode === 'gemma') ids.push(['Gemma', uzmedGemmaId()]);
    else if (mode === 'both') { ids.push(['Qwen', uzmedQwenId()]); ids.push(['Gemma', uzmedGemmaId()]); }

    let llmAnswers = [];
    if (mode !== 'kb' && uzmedWebGPUOk()) {
      const messages = uzmedAiMessages(text, grounding);
      for (let i = 0; i < ids.length; i++) {
        const label = ids[i][0], id = ids[i][1];
        if (!uzmedHaveModel(id)) continue;       // model hali yuklab olinmagan — o'tkazib yuboramiz
        try {
          const t = await uzmedGen(id, messages);
          if (t && t.trim()) llmAnswers.push({ label: label, text: t.trim() });
        } catch (e) {}                            // generatsiya xatosi — ichki bazaga tushadi
      }
    }

    hideTyping();

    let answerForHistory;
    if (llmAnswers.length >= 2) {
      llmAnswers.sort(function(a, b){ return scoreAnswer(b.text) - scoreAnswer(a.text); });
      appendCombinedBotMsg(llmAnswers[0], llmAnswers[1], kbMatched);
      answerForHistory = llmAnswers[0].text;
    } else if (llmAnswers.length === 1) {
      appendModelBotMsg(llmAnswers[0].label, llmAnswers[0].text, kbMatched);
      answerForHistory = llmAnswers[0].text;
    } else {
      // Oflayn AI yo'q (WebGPU yo'q / model yuklanmagan / xato) — ichki baza javobi
      appendBotMsg(local);
      answerForHistory = local;
    }
    aiHistory.push({ role: 'model', parts: [{ text: answerForHistory }] });
    try{ if(window.aiTarixAdd) window.aiTarixAdd(text, answerForHistory); }catch(e){}
  } catch (err) {
    hideTyping();
    const ans = localUzmedAiAnswer(text);
    appendBotMsg(ans);
    aiHistory.push({ role: 'model', parts: [{ text: ans }] });
  }

  aiTyping = false;
  document.getElementById('aiSendBtn').disabled = false;
  document.getElementById('aiInput').focus();
}


/* ════ AI TARIXI (qidiruv tarixi, localStorage) ════ */
function aiTarixEsc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function aiTarixLoad(){ try{ return JSON.parse(localStorage.getItem('UZMED_AI_TARIX')||'[]'); }catch(e){ return []; } }
function aiTarixSave(a){ try{ localStorage.setItem('UZMED_AI_TARIX', JSON.stringify((a||[]).slice(0,200))); }catch(e){} }
window.aiTarixAdd = function(q, ans){
  if(!q || !String(q).trim()) return;
  var a=aiTarixLoad();
  a.unshift({ q:String(q).slice(0,200), a:String(ans||'').replace(/<img[^>]*>/g,'').slice(0,500), t:Date.now() });
  aiTarixSave(a); window.aiTarixUpdateBadge();
};
window.aiTarixUpdateBadge = function(){
  var n=aiTarixLoad().length;
  var b=document.getElementById('cartBadge'); if(b) b.textContent=n;
  var c=document.getElementById('aiTarixCount'); if(c) c.textContent=n+' ta yozuv';
};
window.aiTarixClear = function(){
  if(!confirm('AI tarixini butunlay tozalashni xohlaysizmi?')) return;
  aiTarixSave([]); window.aiTarixRender(); window.aiTarixUpdateBadge();
  if(window.toast) toast('AI tarixi tozalandi');
};
window.aiTarixRender = function(){
  var list=document.getElementById('aiTarixList'); if(!list) return;
  var a=aiTarixLoad();
  if(!a.length){ list.innerHTML='<div style="text-align:center;color:var(--muted);padding:48px 12px;line-height:1.6">Hozircha tarix boʼsh.<br>UZMED AI orqali biror narsa qidiring — shu yerda saqlanadi.</div>'; return; }
  list.innerHTML=a.map(function(it,ix){
    var d=new Date(it.t||Date.now());
    var ds=('0'+d.getDate()).slice(-2)+'.'+('0'+(d.getMonth()+1)).slice(-2)+'.'+d.getFullYear()+' '+('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);
    var prev=aiTarixEsc(String(it.a||'').replace(/[*#>`]/g,'').replace(/\n+/g,' ').slice(0,100));
    return '<div onclick="aiTarixReask('+ix+')" style="background:var(--white);border:1px solid var(--border);border-radius:12px;padding:12px 14px;margin-bottom:10px;cursor:pointer">'
      +'<div style="font-weight:700;color:var(--text);font-size:14px;margin-bottom:4px"><i class=uzi44></i> '+aiTarixEsc(it.q)+'</div>'
      +(prev?'<div style="font-size:12px;color:var(--muted);line-height:1.5">'+prev+'…</div>':'')
      +'<div style="font-size:11px;color:var(--muted);margin-top:6px">'+ds+'</div></div>';
  }).join('');
};
window.aiTarixReask = function(ix){
  var a=aiTarixLoad(); var it=a[ix]; if(!it) return;
  if(window.showNav) showNav('doktor');
  if(window.switchAiMode) switchAiMode('chat');
  setTimeout(function(){
    var inp=document.getElementById('aiInput');
    if(inp){ inp.value=it.q; }
    if(typeof sendAiMessage==='function') sendAiMessage();
  },120);
};
window.openAiTarix = function(){
  if(window.aiTarixRender) aiTarixRender();
  if(window.aiTarixUpdateBadge) aiTarixUpdateBadge();
  if(window.showScreen) showScreen('ai-tarix-screen');
};
try{ document.addEventListener('DOMContentLoaded',function(){ if(window.aiTarixUpdateBadge) aiTarixUpdateBadge(); }); }catch(e){}

function sendChip(text) {
  document.getElementById('aiInput').value = text;
  sendAiMessage();
}

