// ── STATE ──
let currentScreen='assosi-screen';
let screenStack=[];
let selectedDiag=null;
let drugSource='all';
let drugFilter='';
let drugSort='default';

const drugByInn={};
DRUGS.forEach(d=>{
  const k=d.inn.toLowerCase();
  if(!drugByInn[k]) drugByInn[k]=[];
  drugByInn[k].push(d);
});

function getDrugsForInns(inns){
  const res={};
  inns.forEach(inn=>{
    const k=inn.toLowerCase();
    let found=[];
    Object.keys(drugByInn).forEach(dk=>{
      if(dk===k||dk.includes(k)||k.includes(dk)){
        drugByInn[dk].forEach(d=>{if(!found.find(x=>x.id===d.id)) found.push(d);});
      }
    });
    if(found.length) res[inn]=found;
  });
  return res;
}
function parseP(s){return parseFloat(String(s).replace(/\s/g,'').replace(',','.'))||0;}
const curTag={'Узбекский сум':'tag-uzs','Доллар США':'tag-usd','Евро':'tag-eur','Российский рубль':'tag-rub'};
const curLabel={'Узбекский сум':'UZS','Доллар США':'USD','Евро':'EUR','Российский рубль':'RUB'};
const drugEmoji=['<i class=uzi10></i>','<i class=uzi11></i>','<i class=uzi48></i>','<i class=uzi12></i>','<i class=uzi16></i>','<i class=uzi112></i>'];

function showNav(name){
  screenStack=[];
  showScreen(name+'-screen');
  document.querySelectorAll('.nav-item').forEach(b=>{b.classList.remove('active');});
  const nb=document.getElementById('nav-'+name);
  if(nb) nb.classList.add('active');
}
function showScreen(id){
  document.querySelectorAll('.screen').forEach(s=>{s.classList.remove('active');s.scrollTop=0;});
  const sc=document.getElementById(id);
  if(sc) sc.classList.add('active');
  currentScreen=id;
}
function pushScreen(id){
  screenStack.push(currentScreen);
  showScreen(id);
}
function goBack(){
  if(screenStack.length){const prev=screenStack.pop();showScreen(prev);}
  else{showNav('assosi');}
}

// ── DERMA MODAL ──
function openDermaModal(key){
  const d=DERMA_DATA[key];
  if(!d) return;
  const imgSrc = DISEASE_IMGS[key];
  if (imgSrc) {
    document.getElementById('modalIcon').innerHTML='<img src="'+imgSrc+'" style="width:100%;height:100%;object-fit:cover;border-radius:12px;" alt="">';
    document.getElementById('modalIcon').className='derma-modal-icon';
  } else {
    document.getElementById('modalIcon').innerHTML='<div style="width:100%;height:100%;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:22px;">'+d.icon+'</div>';
    document.getElementById('modalIcon').className='derma-modal-icon '+d.bg;
  }
  document.getElementById('modalIcon').className='derma-modal-icon '+d.bg;
  document.getElementById('modalTitle').textContent=d.uz;

  const sevColors={CRITICAL:'#fee2e2',SEVERE:'#fef3c7',MODERATE:'#dbeafe',MILD:'#dcfce7'};
  const sevText={CRITICAL:'#991b1b',SEVERE:'#92400e',MODERATE:'#1d4ed8',MILD:'#15803d'};

  const galleryHtml = imgSrc ? `
    <div class="modal-section">
      <div class="modal-section-title"><i class=uzi83></i> Klinik rasm</div>
      <img src="${imgSrc}" style="width:100%;border-radius:10px;margin-bottom:4px;" alt="klinik rasm">
    </div>` : '';
  document.getElementById('modalBody').innerHTML= galleryHtml + `
    <div class="modal-ru">${d.ru}</div>
    <div class="modal-tags-row">
      <span class="modal-tag" style="background:var(--red-soft);color:var(--red);font-family:monospace">${d.mkb}</span>
      <span class="modal-tag" style="background:${sevColors[d.sev]||'#f5f5f5'};color:${sevText[d.sev]||'#333'}">${d.sev}</span>
    </div>
    <div class="modal-section">
      <div class="modal-section-title"><i class=uzi73></i> Ta’rif (UZ)</div>
      <div class="modal-section-text">${d.tarif}</div>
    </div>
    <div class="modal-section">
      <div class="modal-section-title"><i class=uzi73></i> Описание (RU)</div>
      <div class="modal-section-text" style="color:var(--muted)">${d.rus_tarif}</div>
    </div>
    <div class="modal-section">
      <div class="modal-section-title"><i class=uzi43></i> Klinik belgilar</div>
      <div class="modal-section-text" style="white-space:pre-line">${d.belgilar}</div>
    </div>
    <div class="modal-section">
      <div class="modal-section-title"><i class=uzi10></i> Davolash</div>
      <div class="modal-section-text" style="white-space:pre-line;color:var(--red);font-weight:700">${d.davolash}</div>
    </div>
    <div class="modal-section">
      <div class="modal-section-title"><i class=uzi153></i> Muhim chegara</div>
      <div class="modal-section-text" style="background:var(--red-soft);padding:8px 10px;border-radius:8px;font-weight:700">${d.chegara}</div>
    </div>
    <div class="modal-section">
      <div class="modal-section-title"><i class=uzi69></i> Differensial tashxis</div>
      <div class="modal-section-text">${d.farq}</div>
    </div>
  `;
  document.getElementById('dermaModal').classList.add('open');
}
function closeDermaModal(){
  document.getElementById('dermaModal').classList.remove('open');
}
function closeDermaModalBg(e){
  if(e.target===document.getElementById('dermaModal')) closeDermaModal();
}

// ── CATEGORY SCREEN ──
function showCatScreen(key,icon,title){
  const sec=MKB_SECTIONS[key];
  if(!sec) return;
  document.getElementById('catScreenTitle').textContent=icon+' '+title;
  document.getElementById('catScreenCount').textContent='Kodlar: '+sec.codes.length;
  const list=document.getElementById('catScreenList');
  list.innerHTML='';
  sec.codes.forEach((code,i)=>{
    const item=document.createElement('div');
    item.className='mkb-item'+(code.group?' group':'');
    item.style.animationDelay=(i*0.04)+'s';
    item.innerHTML='<div class="mkb-code-badge">'+code.code+'</div><div class="item-info"><div class="mkb-uz">'+code.uz+'</div><div class="mkb-ru">'+code.ru+'</div></div><div class="mkb-arrow">›</div>';
    item.addEventListener('click',()=>showDrugScreen(code,sec));
    list.appendChild(item);
  });
  pushScreen('cat-screen');
}

// ── DRUG SCREEN ──
function showDrugScreen(code,section){
  selectedDiag={code,section};
  drugSource='all';drugFilter='';drugSort='default';
  if(document.getElementById('drugFilterInput')) document.getElementById('drugFilterInput').value='';
  if(document.getElementById('drugSort')) document.getElementById('drugSort').value='default';
  document.querySelectorAll('.src-tab-btn').forEach(b=>b.classList.remove('active'));
  const firstTab=document.querySelector('.src-tab-btn');
  if(firstTab) firstTab.classList.add('active');
  document.getElementById('drugScreenTop').innerHTML='<div class="diag-code">'+code.code+'</div><h2>'+code.uz+'</h2><div class="diag-ru">'+code.ru+'</div><div class="sec-tag">'+section.icon+' '+section.title+'</div>';
  renderDrugList();
  pushScreen('drug-screen');
}
function setDrugSource(btn,src){drugSource=src;document.querySelectorAll('.src-tab-btn').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderDrugList();}
function setDrugFilter(v){drugFilter=v;renderDrugList();}
function setDrugSort(v){drugSort=v;renderDrugList();}

function renderDrugList(){
  if(!selectedDiag) return;
  const {code}=selectedDiag;
  const inns=code.inns||[];
  const container=document.getElementById('drugScreenList');
  container.innerHTML='';
  let total=0;
  const drugMap=getDrugsForInns(inns);
  const filter=drugFilter.toLowerCase().trim();
  inns.forEach(inn=>{
    let drugs=(drugMap[inn]||[]).slice();
    if(drugSource==='adti') drugs=drugs.filter(d=>!d.source);
    if(drugSource==='vidal') drugs=drugs.filter(d=>d.source==='vidal');
    if(filter) drugs=drugs.filter(d=>d.brand.toLowerCase().includes(filter)||(d.manufacturer||'').toLowerCase().includes(filter));
    if(drugSort==='asc') drugs.sort((a,b)=>parseP(a.retail)-parseP(b.retail));
    else if(drugSort==='desc') drugs.sort((a,b)=>parseP(b.retail)-parseP(a.retail));
    else if(drugSort==='brand') drugs.sort((a,b)=>a.brand.localeCompare(b.brand));
    if(!drugs.length) return;
    total+=drugs.length;
    const prices=drugs.filter(d=>d.currency==='Узбекский сум').map(d=>parseP(d.retail)).filter(Boolean);
    const minP=prices.length?Math.min(...prices):0;
    const maxP=prices.length?Math.max(...prices):0;
    const block=document.createElement('div');
    block.className='inn-group-block';
    const hdr=document.createElement('div');
    hdr.className='inn-group-hdr';
    const priceStr=prices.length>1?'<span class="inn-price-range">'+fmtN(minP)+'–'+fmtN(maxP)+'</span>':'';
    hdr.innerHTML='<span class="inn-icon"><i class=uzi10></i></span><span class="inn-label">'+inn+'</span><span class="inn-cnt-chip">'+drugs.length+'</span>'+priceStr+'<span class="inn-toggle-arr up" id="arr_'+inn.replace(/\s/g,'_')+'">▲</span>';
    const cardWrap=document.createElement('div');
    cardWrap.id='wrap_'+inn.replace(/\s/g,'_');
    drugs.forEach((d,i)=>{
      const verified=d.currency==='Узбекский сум';
      const p=verified?parseP(d.retail):0;
      const displayedPrice=verified?d.retail:'Narx tekshirilmoqda';
      const isCheap=prices.length>1&&p===minP&&p>0;
      const isPricey=prices.length>1&&p===maxP&&p>0;
      const tag=curTag[d.currency]||'tag-int';
      const label=verified?'UZS':'';
      const icon=drugEmoji[i%drugEmoji.length];
      const card=document.createElement('div');
      card.className='drug-card';
      card.style.animationDelay=(i*0.03)+'s';
      card.innerHTML='<div class="drug-card-img">'+icon+'</div><div class="drug-card-body"><div class="drug-brand">'+d.brand+'</div><div class="drug-mfr">'+d.manufacturer+'</div><div class="drug-pkg">'+d.package+'</div><div class="drug-price-row"><div class="drug-price">'+displayedPrice+' <span>'+label+'</span></div>'+(isCheap?'<span class="price-tag tag-cheap">ARZON</span>':'')+(isPricey?'<span class="price-tag tag-pricey">QIMMAT</span>':'')+(!isCheap&&!isPricey?'<span class="price-tag '+tag+'">'+label+'</span>':'')+'</div></div>';
      card.addEventListener('click',()=>toast('<i class=uzi10></i> '+d.brand+' — '+displayedPrice+' '+label));
      cardWrap.appendChild(card);
    });
    hdr.addEventListener('click',()=>{
      const arr=document.getElementById('arr_'+inn.replace(/\s/g,'_'));
      if(cardWrap.style.display==='none'){cardWrap.style.display='';if(arr) arr.classList.add('up');}
      else{cardWrap.style.display='none';if(arr) arr.classList.remove('up');}
    });
    block.appendChild(hdr);block.appendChild(cardWrap);container.appendChild(block);
  });
  if(!total){
    container.innerHTML='<div class="no-result"><div class="no-icon"><i class=uzi10></i></div><p>'+(filter?'Filtrlash bo\'yicha dori topilmadi':'Dori ma\'lumoti mavjud emas')+'</p></div>';
  } else {
    const btn=document.createElement('button');
    btn.className='find-btn';
    btn.innerHTML='<i class=uzi22></i> Dorixonada topish';
    btn.addEventListener('click',()=>toast('Dorixonalar qidirilmoqda...'));
    container.appendChild(btn);
  }
}

// ── GLOBAL SEARCH ──
function doGlobalSearch(q){
  const res=document.getElementById('searchResults');
  res.innerHTML='';
  if(!q.trim()) return;
  const lq=q.toLowerCase();
  let found=0;
  Object.entries(MKB_SECTIONS).forEach(([key,sec])=>{
    sec.codes.forEach(code=>{
      if(code.code.toLowerCase().includes(lq)||code.uz.toLowerCase().includes(lq)||code.ru.toLowerCase().includes(lq)){
        const item=document.createElement('div');
        item.className='mkb-item';
        item.innerHTML='<div class="mkb-code-badge">'+code.code+'</div><div class="item-info"><div class="mkb-uz">'+code.uz+'</div><div class="mkb-ru">'+sec.icon+' '+sec.title+'</div></div><div class="mkb-arrow">›</div>';
        item.addEventListener('click',()=>showDrugScreen(code,sec));
        res.appendChild(item);found++;
      }
    });
  });
  if(!found) res.innerHTML='<div class="no-result"><div class="no-icon"><i class=uzi43></i></div><p>Natija topilmadi</p></div>';
}

function toast(msg){
  const t=document.getElementById('toastEl');
  t.innerHTML=msg;t.classList.add('show');
  clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),2200);
}
