function fmtN(n){return Math.round(n).toLocaleString('uz-UZ');}

function updateNotif(cb){
  document.getElementById('notifVal').textContent = cb.checked ? 'Yoqilgan' : 'O\'chirilgan';
  toast(cb.checked ? '<i class=uzi60></i> Bildirishnomalar yoqildi' : '<i class=uzi61></i> O\'chirildi');
}
function toggleNotif(row){
  const cb = document.getElementById('notifToggle');
  cb.checked = !cb.checked;
  updateNotif(cb);
}
function applyTheme(isDark){
  document.body.classList.toggle('dark-mode', isDark);
  var cb = document.getElementById('themeToggle');
  if(cb) cb.checked = isDark;
  document.getElementById('themeVal').textContent = isDark ? 'Tungi' : 'Kunduzgi';
  const icon = document.getElementById('themeIcon');
  icon.innerHTML = isDark
    ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#9598a8" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>'
    : '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#9598a8" stroke-width="2"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>';
  try{ localStorage.setItem('uzmed_theme', isDark ? 'dark' : 'light'); }catch(e){}
  toast(isDark ? '<i class=uzi62></i> Tungi rejim yoqildi' : '<i class=uzi63></i> Kunduzgi rejim yoqildi');
}
function toggleTheme(){
  // single source of truth — read current body state, flip it
  const isDarkNow = document.body.classList.contains('dark-mode');
  applyTheme(!isDarkNow);
}
// Restore saved theme on load (default = Day/Kunduzgi)
(function initTheme(){
  function boot(){
    var saved = null;
    try{ saved = localStorage.getItem('uzmed_theme'); }catch(e){}
    applyTheme(saved === 'dark');
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();


