// в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
// showAllergyDrugDetail вЂ” dori tafsiloti modal (DOM-dan ma’lumot oladi)
// в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
function showAllergyDrugDetail(inn, brand, mfr, pkg, price, cur){
  const key = (inn||'').toLowerCase().replace(/\s+/g,' ').trim();
  const d = ALLERGY_DRUG_DETAILS[key] || null;
  const bodyEl = document.getElementById('allergyDrugModalBody');
  if(!bodyEl) return;

  let html = '<div style="display:flex;align-items:center;gap:10px;margin-bottom:14px">' +
    '<div style="font-size:30px">рџ’Љ</div>' +
    '<div><div style="font-size:18px;font-weight:800;color:var(--text);line-height:1.2">' + (brand||inn) + '</div>' +
    '<div style="font-size:12px;color:var(--muted);margin-top:2px">' + (inn?inn.charAt(0).toUpperCase()+inn.slice(1):'') + '</div></div>' +
    '</div>';

  if(d){
    html += '<div class="adm-chip-row"><span class="adm-chip-cat adm-chip">' + d.cat + '</span></div>';
    if(d.brands) html += adm_sec('рџЏ·пёЏ','Brendlar',d.brands);
    if(d.form) html += adm_sec('рџ“‹','Shakli',d.form);
    if(d.dose) html += '<div class="adm-section"><div class="adm-sec-title">рџ’Љ Dozalash (yoshga qarab)</div>' +
      '<div class="adm-sec-body">' + d.dose.replace(/\|/g,'<br>') + '</div></div>';
    if(d.max) html += '<div class="adm-field"><span class="adm-lbl">в¬†пёЏ Maks. doza</span><span class="adm-val">' + d.max + '</span></div>';
    if(d.contra) html += '<div class="adm-section adm-section-red"><div class="adm-sec-title">рџљ« Qarshi ko\'rsatmalar</div><div class="adm-sec-body">' + d.contra + '</div></div>';
    if(d.side) html += '<div class="adm-section adm-section-orange"><div class="adm-sec-title">вљ пёЏ Yon ta\'sirlar</div><div class="adm-sec-body">' + d.side + '</div></div>';
    if(d.emerg) html += '<div class="adm-section adm-section-emergency"><div class="adm-sec-title">рџљЁ Shoshilinch</div><div class="adm-sec-body">' + d.emerg + '</div></div>';
    if(d.note) html += '<div class="adm-section adm-section-blue"><div class="adm-sec-title">рџ“ќ Eslatma</div><div class="adm-sec-body">' + d.note + '</div></div>';
  } else {
    html += '<div class="adm-section"><div class="adm-sec-body" style="color:var(--muted)">Bu dori uchun qo\'shimcha klinik ma\'lumot mavjud emas.</div></div>';
  }

  if(price && String(price).trim() && String(price).trim() !== '0') {
    html += '<div class="adm-price-row"><span style="font-size:13px;color:var(--muted)">рџ’° Narxi:</span>' +
      '<span style="font-size:16px;font-weight:800;color:var(--green)">' + price + ' <span style="font-size:11px;font-weight:500">' + (cur||'UZS') + '</span></span></div>';
  }
  if(mfr) html += '<div style="margin-top:8px;font-size:11px;color:var(--muted)">рџЏ­ Ishlab chiqaruvchi: ' + mfr + '</div>';
  if(pkg) html += '<div style="margin-top:4px;font-size:11px;color:var(--muted)">рџ“¦ Qadoqlanishi: ' + pkg + '</div>';

  bodyEl.innerHTML = html;
  document.getElementById('allergyDrugModal').classList.add('open');
}
function adm_sec(icon, label, value){
  return '<div class="adm-section"><div class="adm-sec-title">'+icon+' '+label+'</div><div class="adm-sec-body">'+value+'</div></div>';
}
function closeAllergyDrugModal(){
  document.getElementById('allergyDrugModal').classList.remove('open');
}
function closeAllergyDrugModalBg(e){
  if(e.target===document.getElementById('allergyDrugModal')) closeAllergyDrugModal();
}

const _origShowAllergyDrugDetail = showAllergyDrugDetail;
function fdmSwitch(tab){
  document.querySelectorAll('.fdm-tab').forEach(t=>t.classList.toggle('active', t.dataset.tab===tab));
  const body = document.getElementById('fdm-tab-body');
  if(body) body.innerHTML = window._fdmTabs ? (window._fdmTabs[tab]||'') : '';
  if(body) body.scrollTop = 0;
}
function closeFdmModal(){
  document.getElementById('fdmModal').classList.remove('open');
  document.body.style.overflow='';
}
function closeFdmBg(e){ if(e.target===document.getElementById('fdmModal')) closeFdmModal(); }
function openClinicalMonograph(inn, brand, mfr, pkg, price, cur){
  const key = (inn||'').toLowerCase().replace(/\s+/g,' ').trim();
  const fd = (window.FULL_DRUG_DB && window.FULL_DRUG_DB[key]) ? window.FULL_DRUG_DB[key] : null;
  const d = fd || {
    name: brand||inn,
    shakl: pkg||'',
    korsatmalar: '',
    dozalash: '',
    qarshi: '',
    yon: '',
    talsiruvi: '',
    eslatma: ''
  };
  const title = brand || d.name || inn;
  const subtitle = (d.name || inn) + (d.shakl ? ' · '+d.shakl : '');
  const modal = document.getElementById('fdmModal');
  if(!modal) return;
  document.getElementById('fdm-title').textContent = title;
  document.getElementById('fdm-subtitle').textContent = subtitle;
  document.getElementById('fdm-price').textContent = (price && String(price).trim() && String(price)!=='0') ? price+' '+(cur||'') : '';
  window._fdmTabs = {
    general: '<div class="fdm-field"><span>Xalqaro nomi</span><b>'+esc(d.name||title)+'</b></div>' +
             '<div class="fdm-field"><span>Shakli</span><b>'+esc(d.shakl)+'</b></div>' +
             '<div class="fdm-field"><span>Ishlab chiqaruvchi</span><b>'+esc(mfr||'')+'</b></div>' +
             '<div class="fdm-desc">'+esc(d.korsatmalar||d.eslatma||'Ma’lumot mavjud emas.')+'</div>',
    comp: '<div class="fdm-sec">Tarkib</div><div class="fdm-body">'+esc(d.shakl)+'</div>',
    ind: '<div class="fdm-sec">Ko‘rsatmalar</div><div class="fdm-body">'+esc(d.korsatmalar)+'</div>',
    dose: '<div class="fdm-sec">Dozalash</div><div class="fdm-body">'+esc(d.dozalash)+'</div>',
    contra: '<div class="fdm-sec fdm-red">Qarshi</div><div class="fdm-body">'+esc(d.qarshi)+'</div>',
    side: '<div class="fdm-sec fdm-orange">Yon ta\'sir</div><div class="fdm-body">'+esc(d.yon)+'</div>' +
          '<div class="fdm-sec fdm-orange">Dori o\'zaro ta\'sir</div><div class="fdm-body">'+esc(d.talsiruvi)+'</div>',
    pharm: '<div class="fdm-sec">Farmakologiya</div><div class="fdm-body">'+esc('')+'</div>',
    warn: '<div class="fdm-sec fdm-red">Eslatma</div><div class="fdm-body">'+esc(d.eslatma)+'</div>',
    preg: '<div class="fdm-sec fdm-purple">Homiladorlik</div><div class="fdm-body">'+esc('')+'</div>' +
          '<div class="fdm-sec fdm-purple">Emizish</div><div class="fdm-body">'+esc('')+'</div>',
    ped: '<div class="fdm-sec fdm-green">Bolalar</div><div class="fdm-body">'+esc('')+'</div>',
    store: '<div class="fdm-sec fdm-blue">Saqlash</div><div class="fdm-body">'+esc('')+'</div>',
    analog: '<div class="fdm-sec">Analoglar</div><div class="fdm-body">'+esc('')+'</div>'
  };
  fdmSwitch('general');
  modal.classList.add('open');
  document.body.style.overflow='hidden';
}
window.showAllergyDrugDetail = function(inn, brand, mfr, pkg, price, cur){
  const key = (inn||'').toLowerCase().replace(/\s+/g,' ').trim();
  if(window.FULL_DRUG_DB && window.FULL_DRUG_DB[key]){
    openClinicalMonograph(inn, brand, mfr, pkg, price, cur);
    return;
  }
  _origShowAllergyDrugDetail(inn, brand, mfr, pkg, price, cur);
};
window.openClinicalMonograph = openClinicalMonograph;

// в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
// Override showDrugScreen to add treatment protocol card
// (runs after showDrugScreen is defined above at line ~2678)
// в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
(function(){
  const _orig = showDrugScreen;
  showDrugScreen = function(code, section){
    _orig.call(this, code, section);
    const proto = DISEASE_PROTOCOLS[code.code];
    if(!proto) return;
    const top = document.getElementById('drugScreenTop');
    if(!top || top.querySelector('.protocol-card')) return;
    const div = document.createElement('div');
    div.className = 'protocol-card';
    let ph = '<div class="protocol-title">рџ“‹ Davolash Protokoli вЂ” ' + code.code + '</div>';
    if(proto.diag) ph += '<div class="protocol-section"><div class="protocol-lbl">рџ”Ќ Tashxis mezonlari</div><div class="protocol-body">' + proto.diag + '</div></div>';
    if(proto.first) ph += '<div class="protocol-section"><div class="protocol-lbl">вњ… Asosiy davo (1-qator)</div><div class="protocol-body">' + proto.first + '</div></div>';
    if(proto.alt) ph += '<div class="protocol-section"><div class="protocol-lbl">рџ”„ Muqobil davo</div><div class="protocol-body">' + proto.alt + '</div></div>';
    if(proto.dose) ph += '<div class="protocol-section"><div class="protocol-lbl">рџ’Љ Dozalar va davomiylik</div><div class="protocol-body">' + proto.dose + '</div></div>';
    if(proto.emerg) ph += '<div class="protocol-section protocol-emergency"><div class="protocol-lbl">рџљЁ Shoshilinch yordam</div><div class="protocol-body">' + proto.emerg + '</div></div>';
    div.innerHTML = ph;
    top.appendChild(div);
  };
})();

// в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
// Event delegation: intercept .drug-db-item clicks for detail card
// (works by reading DOM content вЂ” no data attributes needed)
// в•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђв•ђ
document.addEventListener('click', function(e){
  const item = e.target.closest('#drugDbList .drug-db-item');
  if(!item) return;
  // Walk back to find the INN header
  let sib = item.previousElementSibling;
  while(sib && !sib.classList.contains('drug-db-inn-hdr')) sib = sib.previousElementSibling;
  const inn = sib ? (sib.querySelector('.drug-db-inn-name')||{}).textContent||'' : '';
  const brand = (item.querySelector('.drug-db-brand')||{}).textContent||'';
  const mfr = (item.querySelector('.drug-db-mfr')||{}).textContent||'';
  const pkg = (item.querySelector('.drug-db-pkg')||{}).textContent||'';
  const priceEl = item.querySelector('.drug-db-price');
  let price = '';
  if(priceEl){
    const span = priceEl.querySelector('span');
    price = priceEl.textContent.replace(span?span.textContent:'','').trim();
  }
  const curEl = item.querySelector('.drug-db-cur');
  const cur = curEl ? curEl.textContent.trim() : 'UZS';
  showAllergyDrugDetail(inn, brand, mfr, pkg, price, cur);
}, false);
let drugDbFilter_q = '';
let drugDbGroupFilter = 'ALL';
let drugDbShown = 100;
let drugDbFiltered = [];

