function drugDbFilter(q){
  drugDbFilter_q = q.toLowerCase().trim();
  drugDbGroupFilter = 'ALL';
  document.querySelectorAll('#dorilar-screen .mkb-letter-btn').forEach(b=>b.classList.remove('active'));
  document.querySelector('#dorilar-screen .mkb-letter-btn').classList.add('active');
  document.getElementById('drugDbClear').style.display = q ? 'block' : 'none';
  drugDbShown = 100;
  applyDrugFilters();
}

function clearDrugSearch(){
  document.getElementById('drugDbSearch').value = '';
  drugDbFilter('');
}

function filterDrugByGroup(btn, group){
  drugDbGroupFilter = group;
  drugDbFilter_q = '';
  document.getElementById('drugDbSearch').value = '';
  document.getElementById('drugDbClear').style.display = 'none';
  document.querySelectorAll('#dorilar-screen .mkb-letter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  drugDbShown = 100;
  applyDrugFilters();
}

function applyDrugFilters(){
  if(drugDbFilter_q){
    const q = drugDbFilter_q;
    drugDbFiltered = DRUG_DATA.filter(d =>
      d[0].toLowerCase().includes(q) ||
      d[1].toLowerCase().includes(q) ||
      d[2].toLowerCase().includes(q)
    );
  } else if(drugDbGroupFilter !== 'ALL'){
    if(drugDbGroupFilter === 'uzb'){
      drugDbFiltered = DRUG_DATA.filter(d => d[2].includes('UZ'));
    } else {
      const keywords = DRUG_GROUPS[drugDbGroupFilter] || [];
      drugDbFiltered = DRUG_DATA.filter(d =>
        keywords.some(k => d[1].toLowerCase().includes(k))
      );
    }
  } else {
    drugDbFiltered = DRUG_DATA;
  }
  renderDrugDb();
}

function renderDrugDb(){
  const container = document.getElementById('drugDbList');
  const total = drugDbFiltered.length;
  const shown = Math.min(drugDbShown, total);

  // Group by INN
  const innGroups = {};
  for(let i=0; i<shown; i++){
    const d = drugDbFiltered[i];
    const inn = d[1] || 'Boshqa';
    if(!innGroups[inn]) innGroups[inn] = [];
    innGroups[inn].push(d);
  }

  let html = `<div style="padding:6px 16px;background:var(--bg);font-size:11px;color:var(--muted);font-weight:700">
    ${total.toLocaleString()} ta preparat topildi
  </div>`;

  Object.entries(innGroups).forEach(([inn, list])=>{
    const prices = list.map(d=>parseFloat(String(d[5]).replace(/\s/g,''))||0).filter(Boolean);
    const minP = prices.length ? Math.min(...prices) : 0;
    const maxP = prices.length ? Math.max(...prices) : 0;
    const priceRange = prices.length > 1 ? `${Math.round(minP).toLocaleString()} – ${Math.round(maxP).toLocaleString()} UZS` : '';

    html += `<div class="drug-db-inn-hdr">
      <span style="font-size:14px"><i class=uzi10></i></span>
      <span class="drug-db-inn-name">${inn}</span>
      <span class="drug-db-inn-cnt">${list.length}</span>
      ${priceRange ? `<span style="font-size:9px;color:var(--green);font-weight:700">${priceRange}</span>` : ''}
    </div>`;

    list.forEach((d,i)=>{
      const [brand, inn2, mfr, pkg, cur, retail] = d;
      const price = parseFloat(String(retail).replace(/\s/g,''))||0;
      const isCheap = prices.length>1 && price===minP && price>0;
      html += `<div class="drug-db-item" onclick="toast('<i class=uzi10></i> ${brand} — ${retail} ${cur}')">
        <div style="display:flex;gap:8px;align-items:flex-start">
          <div style="flex:1">
            <div class="drug-db-brand">${brand}</div>
            <div class="drug-db-mfr">${mfr}</div>
            <div class="drug-db-pkg">${pkg}</div>
            <div class="drug-db-price-row">
              <div class="drug-db-price">${retail} <span style="font-size:9px;color:var(--muted)">${cur}</span></div>
              ${isCheap ? '<span class="drug-db-cur" style="background:#dcfce7;color:#15803d">ARZON</span>' : `<span class="drug-db-cur">${cur}</span>`}
            </div>
          </div>
        </div>
      </div>`;
    });
  });

  if(shown < total){
    html += `<button class="mkb-load-more" onclick="drugDbLoadMore()">
      <i class=uzi150></i> Yana ${Math.min(200,total-shown).toLocaleString()} ta yuklash (${(total-shown).toLocaleString()} qoldi)
    </button>`;
  }

  container.innerHTML = html;
}

function drugDbLoadMore(){
  drugDbShown += 200;
  renderDrugDb();
}

// Init drug screen when navigated to
const _origShowNav = showNav;
showNav = function(name){
  _origShowNav(name);
  if(name === 'dorilar'){
    if(!drugDbFiltered.length){
      drugDbFiltered = DRUG_DATA;
      renderDrugDb();
    }
  }
};

// Inject real images into derma cards and modal
function initDermaImages() {
  document.querySelectorAll('.derma-card').forEach(card => {
    const onclick = card.getAttribute('onclick');
    if (!onclick) return;
    const match = onclick.match(/openDermaModal\('(\w+)'\)/);
    if (!match) return;
    const key = match[1];
    const img_src = DISEASE_IMGS[key];
    if (!img_src) return;
    const box = card.querySelector('.derma-img-box');
    if (box) {
      box.innerHTML = '<img src="' + img_src + '" style="width:100%;height:100%;object-fit:cover;border-radius:10px;" alt="">';
    }
  });
}
document.addEventListener('DOMContentLoaded', initDermaImages);


