MKB_DATA.forEach(r=>{r.localAliases=r[3]||[];r.modifierAliases=r[4]||[];r.aliasesVerified=false;r.reference="WHO ICD-10 2019";r.category=/^[A-Z]\d{2}$/.test(r[0]);});
window.MKB_DATA=MKB_DATA;
window.UZMED_MKB_REFERENCE={system:"WHO ICD-10",version:"2019",primaryLanguage:"en",aliasesVerified:false};

let mkbCurrentFilter = '';
let mkbCurrentLetter = 'ALL';
let mkbDisplayCount = 100;
let mkbFiltered = [];

function openMkbDb(){
  mkbCurrentFilter = '';
  mkbCurrentLetter = 'ALL';
  mkbDisplayCount = 100;
  document.getElementById('mkbDbSearch').value = '';
  document.getElementById('mkbDbClear').style.display = 'none';
  document.querySelectorAll('#mkb-db-screen .mkb-letter-btn').forEach(b=>b.classList.remove('active'));
  document.querySelector('#mkb-db-screen .mkb-letter-btn').classList.add('active');
  mkbFiltered = MKB_DATA;
  renderMkbDb();
  pushScreen('mkb-db-screen');
}

function mkbDbFilter(q){
  mkbCurrentFilter = q.toLowerCase().trim();
  mkbCurrentLetter = 'ALL';
  document.querySelectorAll('#mkb-db-screen .mkb-letter-btn').forEach(b=>b.classList.remove('active'));
  document.querySelector('#mkb-db-screen .mkb-letter-btn').classList.add('active');
  document.getElementById('mkbDbClear').style.display = q ? 'block' : 'none';
  mkbDisplayCount = 100;
  applyMkbFilters();
}

function clearMkbSearch(){
  document.getElementById('mkbDbSearch').value = '';
  mkbDbFilter('');
}

function filterByLetter(btn, letter){
  mkbCurrentLetter = letter;
  mkbCurrentFilter = '';
  document.getElementById('mkbDbSearch').value = '';
  document.getElementById('mkbDbClear').style.display = 'none';
  document.querySelectorAll('#mkb-db-screen .mkb-letter-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  mkbDisplayCount = 100;
  applyMkbFilters();
}

function applyMkbFilters(){
  if(mkbCurrentFilter){
    const q = mkbCurrentFilter;
    mkbFiltered = window.UZMED_REFERENCE_SEARCH.searchMkb(MKB_DATA, q, MKB_DATA.length);
  } else if(mkbCurrentLetter !== 'ALL'){
    mkbFiltered = MKB_DATA.filter(r => r[0].startsWith(mkbCurrentLetter));
  } else {
    mkbFiltered = MKB_DATA;
  }
  renderMkbDb();
}

function isClassRow(kod){
  return /^[A-Z]\d{2}-[A-Z]\d{2}$/.test(kod);
}

function renderMkbDb(){
  const container = document.getElementById('mkbDbList');
  // Fallback: if opened via a path that didn't seed the dataset (e.g. side menu),
  // and no active search/letter filter, default to the full list instead of empty.
  if((!mkbFiltered || !mkbFiltered.length) && !mkbCurrentFilter && (mkbCurrentLetter==='ALL' || !mkbCurrentLetter)){
    mkbFiltered = MKB_DATA;
  }
  const total = mkbFiltered.length;
  const shown = Math.min(mkbDisplayCount, total);
  document.getElementById('mkbDbCount').textContent = total.toLocaleString() + ' ta kod · WHO ICD-10 2019 (English)';

  let html = '';
  for(let i=0; i<shown; i++){
    const r = mkbFiltered[i];
    const isClass = isClassRow(r[0]);
    html += `<div class="mkb-db-item${isClass?' is-class':''}">
      <div class="mkb-db-code">${r[0]}</div>
      <div style="flex:1">
        <div class="mkb-db-uz">${r[1]}</div>
        <div class="mkb-db-ru">${r[2]}</div>
      </div>
    </div>`;
  }

  if(shown < total){
    html += `<button class="mkb-load-more" onclick="mkbLoadMore()">
      <i class=uzi150></i> Yana ${Math.min(200, total-shown).toLocaleString()} ta yuklash (${(total-shown).toLocaleString()} qoldi)
    </button>`;
  }

  container.innerHTML = html;
}

function mkbLoadMore(){
  mkbDisplayCount += 200;
  renderMkbDb();
  // Scroll to bottom of new items
  const sc = document.getElementById('mkb-db-screen');
  sc.scrollTop = sc.scrollTop + 600;
}

if ('serviceWorker' in navigator &&
    (location.protocol === 'https:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1')) {
  // Service workers only register over https/localhost. On file:// the single
  // bundled HTML is already fully offline, so we skip registration (and its
  // console warning) there. Companion service-worker.js is shipped for hosting.
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('service-worker.js')
      .then(reg => console.log('UZMED PWA Service Worker registered:', reg.scope))
      .catch(err => console.warn('UZMED PWA registration failed:', err));
  });
}

// в”Ђв”Ђ DOZALASH JADVALI в”Ђв”Ђ
function toggleDoza(id){
  const sec = document.getElementById(id);
  if(!sec) return;
  sec.classList.toggle('open');
}

